  "admirably": {img:"👏", ex5:[{t:1,en:"She handled the crisis admirably.",kr:"그녀는 그 위기를 훌륭하게 처리했다."},{t:2,en:"He performed admirably under pressure.",kr:"그는 압박 속에서도 훌륭하게 해냈다."},{t:3,en:"The team worked admirably together.",kr:"그 팀은 훌륭하게 협력했다."},{t:4,en:"The plan suited their needs admirably.",kr:"그 계획은 그들의 필요에 더없이 잘 맞았다."},{t:5,en:"She remained admirably calm throughout.",kr:"그녀는 내내 감탄스러울 만큼 침착했다."}]},
  "admiral": {img:"⚓", ex5:[{t:1,en:"The admiral commanded.",kr:"제독이 지휘했다."},{t:2,en:"The admiral is respected.",kr:"그 제독은 존경받는다."},{t:3,en:"We saluted the admiral.",kr:"우리는 제독에게 경례했다."},{t:4,en:"The navy gave the admiral a fleet.",kr:"해군은 제독에게 함대를 주었다."},{t:5,en:"We found the admiral wise.",kr:"우리는 그 제독이 현명하다고 느꼈다."}]},
  "admiration": {img:"😍", ex5:[{t:1,en:"Admiration grew.",kr:"감탄이 커졌다."},{t:2,en:"Her admiration was clear.",kr:"그녀의 감탄은 분명했다."},{t:3,en:"We felt admiration.",kr:"우리는 감탄을 느꼈다."},{t:4,en:"The feat gave us admiration.",kr:"그 위업은 우리에게 감탄을 안겼다."},{t:5,en:"We found our admiration genuine.",kr:"우리는 우리의 감탄이 진심임을 알았다."}]},
  "admire": {img:"🤩", ex5:[{t:1,en:"Crowds admire.",kr:"군중이 감탄한다."},{t:2,en:"The view is admirable.",kr:"그 경치는 감탄스럽다."},{t:3,en:"I admire her.",kr:"나는 그녀를 존경한다."},{t:4,en:"The art gave us much to admire.",kr:"그 예술은 우리에게 감탄할 많은 것을 주었다."},{t:5,en:"We admire him brave.",kr:"우리는 그를 용감하다고 우러러본다."}]},
  "admired": {img:"🌟", ex5:[{t:1,en:"He is widely admired.",kr:"그는 널리 존경받는다."},{t:2,en:"The painting is admired.",kr:"그 그림은 찬사를 받는다."},{t:3,en:"We admired the view.",kr:"우리는 그 경치에 감탄했다."},{t:4,en:"The work gave her an admired name.",kr:"그 작품은 그녀에게 존경받는 명성을 주었다."},{t:5,en:"We found the leader admired.",kr:"우리는 그 지도자가 존경받는 것을 알았다."}]},
  "admirer": {img:"💖", ex5:[{t:1,en:"An admirer waited.",kr:"한 팬이 기다렸다."},{t:2,en:"He is a secret admirer.",kr:"그는 남몰래 좋아하는 사람이다."},{t:3,en:"She thanked the admirer.",kr:"그녀는 그 팬에게 감사했다."},{t:4,en:"An admirer sent her flowers.",kr:"한 팬이 그녀에게 꽃을 보냈다."},{t:5,en:"We found the admirer sincere.",kr:"우리는 그 팬이 진실하다고 느꼈다."}]},
  "admission": {img:"🎫", ex5:[{t:1,en:"Admission is free.",kr:"입장은 무료이다."},{t:2,en:"The admission was honest.",kr:"그 고백은 솔직했다."},{t:3,en:"We paid admission.",kr:"우리는 입장료를 냈다."},{t:4,en:"The school gave her admission.",kr:"그 학교는 그녀에게 입학을 허가했다."},{t:5,en:"We found his admission surprising.",kr:"우리는 그의 시인이 놀랍다고 느꼈다."}]},
