  "agony": {img:"😫", ex5:[{t:1,en:"The agony deepened.",kr:"고통이 깊어졌다."},{t:2,en:"The agony is unbearable.",kr:"그 고통은 견디기 힘들다."},{t:3,en:"He hid his agony.",kr:"그는 자신의 고통을 숨겼다."},{t:4,en:"The injury gave him agony.",kr:"그 부상은 그에게 고통을 안겼다."},{t:5,en:"We found the agony lasting.",kr:"우리는 그 고통이 오래간다고 느꼈다."}]},
  "agree": {img:"🤝", ex5:[{t:1,en:"They agree.",kr:"그들은 동의한다."},{t:2,en:"The terms are agreeable.",kr:"그 조건들은 받아들일 만하다."},{t:3,en:"We agree the plan.",kr:"우리는 그 계획에 동의한다."},{t:4,en:"The talks gave us reason to agree.",kr:"그 회담은 우리에게 동의할 이유를 주었다."},{t:5,en:"We agree the deal final.",kr:"우리는 그 거래를 최종으로 합의한다."}]},
  "agreed": {img:"✅", ex5:[{t:1,en:"The price was agreed.",kr:"가격이 합의되었다."},{t:2,en:"The terms are agreed.",kr:"그 조건들은 합의되었다."},{t:3,en:"They agreed the contract.",kr:"그들은 그 계약에 합의했다."},{t:4,en:"The deal gave us an agreed sum.",kr:"그 거래는 우리에게 합의된 금액을 주었다."},{t:5,en:"We found the plan agreed by all.",kr:"우리는 그 계획이 모두에게 합의된 것을 알았다."}]},
  "agreement": {img:"📝", ex5:[{t:1,en:"The agreement holds.",kr:"그 합의는 유효하다."},{t:2,en:"The agreement is fair.",kr:"그 합의는 공정하다."},{t:3,en:"We signed the agreement.",kr:"우리는 그 합의서에 서명했다."},{t:4,en:"The talks gave us an agreement.",kr:"그 회담은 우리에게 합의를 안겼다."},{t:5,en:"We found the agreement binding.",kr:"우리는 그 합의가 구속력이 있음을 알았다."}]},
  "agreements": {img:"📑", ex5:[{t:1,en:"Agreements multiplied.",kr:"합의가 늘었다."},{t:2,en:"The agreements are signed.",kr:"그 합의들은 서명되었다."},{t:3,en:"We reviewed the agreements.",kr:"우리는 그 합의들을 검토했다."},{t:4,en:"The summit gave us trade agreements.",kr:"그 정상회담은 우리에게 무역 협정을 안겼다."},{t:5,en:"We found the agreements valid.",kr:"우리는 그 합의들이 유효함을 알았다."}]},
  "agrees": {img:"👍", ex5:[{t:1,en:"She agrees.",kr:"그녀는 동의한다."},{t:2,en:"The expert agrees.",kr:"그 전문가는 동의한다."},{t:3,en:"He agrees the point.",kr:"그는 그 요점에 동의한다."},{t:4,en:"The data agrees with us our theory.",kr:"그 데이터는 우리의 이론과 일치한다."},{t:5,en:"She agrees with us readily.",kr:"그녀는 우리에게 선뜻 동의한다."}]},
  "agricultural": {img:"🚜", ex5:[{t:1,en:"Agricultural output grew.",kr:"농업 생산량이 늘었다."},{t:2,en:"The land is agricultural.",kr:"그 땅은 농지이다."},{t:3,en:"We support agricultural reform.",kr:"우리는 농업 개혁을 지지한다."},{t:4,en:"The grant gave us agricultural aid.",kr:"그 보조금은 우리에게 농업 지원을 주었다."},{t:5,en:"We found the agricultural sector strong.",kr:"우리는 농업 부문이 견실하다고 보았다."}]},
  "agriculture": {img:"🌾", ex5:[{t:1,en:"Agriculture feeds nations.",kr:"농업이 나라를 먹여 살린다."},{t:2,en:"Agriculture is vital.",kr:"농업은 필수적이다."},{t:3,en:"We study agriculture.",kr:"우리는 농업을 공부한다."},{t:4,en:"The region gave us rich agriculture.",kr:"그 지역은 우리에게 풍부한 농업을 안겼다."},{t:5,en:"We found agriculture thriving.",kr:"우리는 농업이 번성함을 알았다."}]},
  "ah": {img:"😮", ex5:[{t:1,en:"Ah, I see.",kr:"아, 알겠다."},{t:2,en:"The sigh was a soft ah.",kr:"그 한숨은 부드러운 '아'였다."},{t:3,en:"We heard an ah.",kr:"우리는 '아' 소리를 들었다."},{t:4,en:"The surprise gave us an ah moment.",kr:"그 놀라움은 우리에게 '아' 하는 순간을 주었다."},{t:5,en:"We let out an ah relieved.",kr:"우리는 안도하며 '아' 하고 내뱉었다."}]},
  "ahead": {img:"⏩", ex5:[{t:1,en:"They moved ahead.",kr:"그들은 앞으로 나아갔다."},{t:2,en:"The road is clear ahead.",kr:"앞길이 트여 있다."},{t:3,en:"We planned ahead.",kr:"우리는 미리 계획했다."},{t:4,en:"The lead gave us a path ahead.",kr:"그 선두는 우리에게 나아갈 길을 주었다."},{t:5,en:"We found a challenge ahead.",kr:"우리는 앞에 놓인 도전을 발견했다."}]},
  "aid": {img:"🚑", ex5:[{t:1,en:"Aid arrived.",kr:"원조가 도착했다."},{t:2,en:"The aid is generous.",kr:"그 원조는 후하다."},{t:3,en:"We sent aid.",kr:"우리는 원조를 보냈다."},{t:4,en:"The group gave victims aid.",kr:"그 단체는 피해자들에게 원조를 주었다."},{t:5,en:"We found the aid timely.",kr:"우리는 그 원조가 시의적절하다고 느꼈다."}]},
  "aide": {img:"🧑‍💼", ex5:[{t:1,en:"The aide assisted.",kr:"그 보좌관이 도왔다."},{t:2,en:"The aide is loyal.",kr:"그 보좌관은 충실하다."},{t:3,en:"We briefed the aide.",kr:"우리는 그 보좌관에게 보고했다."},{t:4,en:"The senator gave the aide a task.",kr:"그 상원의원은 보좌관에게 임무를 주었다."},{t:5,en:"We found the aide capable.",kr:"우리는 그 보좌관이 유능하다고 느꼈다."}]},
