  "almanac": {img:"📅", ex5:[{t:1,en:"The farmer consulted an almanac for planting times.",kr:"농부는 파종 시기를 알아보려고 연감을 참고했다."},{t:2,en:"The almanac lists tides and moon phases.",kr:"그 연감은 조수와 달의 위상을 나열한다."},{t:3,en:"She kept an old almanac on the shelf.",kr:"그녀는 오래된 연감을 선반에 보관했다."},{t:4,en:"An almanac predicts the year's weather.",kr:"연감은 그해의 날씨를 예측한다."},{t:5,en:"He checked the almanac for the sunrise time.",kr:"그는 일출 시각을 연감에서 확인했다."}]},
  "almighty": {img:"⚡", ex5:[{t:1,en:"The almighty rules.",kr:"전능자가 다스린다."},{t:2,en:"The power is almighty.",kr:"그 힘은 전능하다."},{t:3,en:"They praised the almighty.",kr:"그들은 전능자를 찬양했다."},{t:4,en:"Faith gave them an almighty hope.",kr:"믿음은 그들에게 전능한 희망을 주었다."},{t:5,en:"We heard an almighty crash.",kr:"우리는 엄청난 굉음을 들었다."}]},
  "almond": {img:"🌰", ex5:[{t:1,en:"The almond cracked.",kr:"아몬드가 깨졌다."},{t:2,en:"The almond is sweet.",kr:"그 아몬드는 달콤하다."},{t:3,en:"We roasted almonds.",kr:"우리는 아몬드를 볶았다."},{t:4,en:"She gave me an almond.",kr:"그녀는 나에게 아몬드를 주었다."},{t:5,en:"We found the almond fresh.",kr:"우리는 그 아몬드가 신선하다고 느꼈다."}]},
  "almonds": {img:"🥜", ex5:[{t:1,en:"Almonds fell.",kr:"아몬드가 떨어졌다."},{t:2,en:"The almonds are salted.",kr:"그 아몬드는 소금이 뿌려져 있다."},{t:3,en:"We ate almonds.",kr:"우리는 아몬드를 먹었다."},{t:4,en:"She gave us almonds.",kr:"그녀는 우리에게 아몬드를 주었다."},{t:5,en:"We found the almonds crunchy.",kr:"우리는 그 아몬드가 바삭하다고 느꼈다."}]},
  "almost": {img:"〽️", ex5:[{t:1,en:"We almost won.",kr:"우리는 거의 이길 뻔했다."},{t:2,en:"The cup is almost full.",kr:"그 컵은 거의 가득 찼다."},{t:3,en:"I almost finished it.",kr:"나는 그것을 거의 끝냈다."},{t:4,en:"The miss almost cost us the game.",kr:"그 실수는 하마터면 우리에게 패배를 안길 뻔했다."},{t:5,en:"We found the work almost done.",kr:"우리는 작업이 거의 끝난 것을 알았다."}]},
  "alms": {img:"🙏", ex5:[{t:1,en:"Alms were given.",kr:"자선금이 베풀어졌다."},{t:2,en:"The alms are modest.",kr:"그 시주는 소박하다."},{t:3,en:"We collected alms.",kr:"우리는 자선금을 모았다."},{t:4,en:"The monk gave the poor alms.",kr:"그 승려는 가난한 이들에게 시주를 베풀었다."},{t:5,en:"We found the alms welcome.",kr:"우리는 그 자선이 고마운 것임을 알았다."}]},
  "alone": {img:"🧍", ex5:[{t:1,en:"She sat alone.",kr:"그녀는 혼자 앉아 있었다."},{t:2,en:"He feels alone.",kr:"그는 외로움을 느낀다."},{t:3,en:"We left him alone.",kr:"우리는 그를 혼자 두었다."},{t:4,en:"Silence gave us a moment alone.",kr:"고요는 우리에게 혼자만의 순간을 주었다."},{t:5,en:"We found her alone.",kr:"우리는 그녀가 혼자 있는 것을 알았다."}]},
  "along": {img:"➡️", ex5:[{t:1,en:"We strolled along.",kr:"우리는 따라 거닐었다."},{t:2,en:"The path runs along.",kr:"그 길이 따라 이어진다."},{t:3,en:"We walked along the river.",kr:"우리는 강을 따라 걸었다."},{t:4,en:"The guide led us along the trail.",kr:"안내자는 우리를 오솔길을 따라 이끌었다."},{t:5,en:"We found benches along the way.",kr:"우리는 길을 따라 벤치들을 발견했다."}]},
  "alongside": {img:"🤝", ex5:[{t:1,en:"They worked alongside.",kr:"그들은 나란히 일했다."},{t:2,en:"The boat is alongside.",kr:"그 배가 옆에 붙어 있다."},{t:3,en:"We stood alongside them.",kr:"우리는 그들 곁에 섰다."},{t:4,en:"The role gave us peers alongside us.",kr:"그 역할은 우리에게 곁에서 함께할 동료를 주었다."},{t:5,en:"We found allies alongside us.",kr:"우리는 우리 곁의 동맹을 발견했다."}]},
  "aloof": {img:"🙄", ex5:[{t:1,en:"He stayed aloof.",kr:"그는 거리를 두었다."},{t:2,en:"She seems aloof.",kr:"그녀는 냉담해 보인다."},{t:3,en:"We found him aloof.",kr:"우리는 그가 쌀쌀맞다고 느꼈다."},{t:4,en:"His manner gave us an aloof feel.",kr:"그의 태도는 우리에게 냉담한 느낌을 주었다."},{t:5,en:"We found the cat aloof.",kr:"우리는 그 고양이가 도도하다고 느꼈다."}]},
  "aloofness": {img:"🧊", ex5:[{t:1,en:"His aloofness made him hard to know.",kr:"그의 냉담함은 그를 알기 어렵게 만들었다."},{t:2,en:"She maintained a cool aloofness.",kr:"그녀는 차가운 거리감을 유지했다."},{t:3,en:"The cat's aloofness is part of its charm.",kr:"그 고양이의 도도함은 매력의 일부다."},{t:4,en:"His aloofness was mistaken for arrogance.",kr:"그의 냉담함은 오만함으로 오해받았다."},{t:5,en:"Her aloofness slowly gave way to warmth.",kr:"그녀의 냉담함은 서서히 따뜻함으로 바뀌었다."}]},
