  "alphabetical": {img:"🔡", ex5:[{t:1,en:"The list is alphabetical.",kr:"그 목록은 알파벳순이다."},{t:2,en:"The order is alphabetical.",kr:"그 순서는 알파벳순이다."},{t:3,en:"We sorted it alphabetical.",kr:"우리는 그것을 알파벳순으로 정렬했다."},{t:4,en:"The index gave us an alphabetical order.",kr:"그 색인은 우리에게 알파벳순 정렬을 주었다."},{t:5,en:"We found the entries alphabetical.",kr:"우리는 그 항목들이 알파벳순임을 알았다."}]},
  "alps": {img:"🏔️", ex5:[{t:1,en:"The Alps tower.",kr:"알프스가 우뚝 솟아 있다."},{t:2,en:"The Alps are snowy.",kr:"알프스는 눈이 덮여 있다."},{t:3,en:"We climbed the Alps.",kr:"우리는 알프스를 등반했다."},{t:4,en:"The trip gave us Alps views.",kr:"그 여행은 우리에게 알프스 전경을 보여주었다."},{t:5,en:"We found the Alps breathtaking.",kr:"우리는 알프스가 숨막히게 아름답다고 느꼈다."}]},
  "already": {img:"✔️", ex5:[{t:1,en:"They already left.",kr:"그들은 이미 떠났다."},{t:2,en:"The food is already cold.",kr:"음식이 벌써 식었다."},{t:3,en:"I already finished it.",kr:"나는 그것을 이미 끝냈다."},{t:4,en:"She already gave me the key.",kr:"그녀는 이미 나에게 열쇠를 주었다."},{t:5,en:"We found the seats already taken.",kr:"우리는 자리가 이미 찬 것을 알았다."}]},
  "alright": {img:"👌", ex5:[{t:1,en:"Everything is alright.",kr:"모든 것이 괜찮다."},{t:2,en:"The result is alright.",kr:"그 결과는 괜찮다."},{t:3,en:"We feel alright.",kr:"우리는 괜찮다고 느낀다."},{t:4,en:"The rest gave us an alright mood.",kr:"휴식은 우리에게 괜찮은 기분을 주었다."},{t:5,en:"We found the plan alright.",kr:"우리는 그 계획이 괜찮다고 느꼈다."}]},
  "also": {img:"➕", ex5:[{t:1,en:"She sings; he also plays.",kr:"그녀는 노래하고, 그도 연주한다."},{t:2,en:"The room is also bright.",kr:"그 방은 또한 밝다."},{t:3,en:"We also need water.",kr:"우리는 물도 필요하다."},{t:4,en:"She also gave me advice.",kr:"그녀는 나에게 조언도 해주었다."},{t:5,en:"We found it also useful.",kr:"우리는 그것이 또한 유용하다고 느꼈다."}]},
  "altar": {img:"⛪", ex5:[{t:1,en:"The altar stood.",kr:"제단이 서 있었다."},{t:2,en:"The altar is sacred.",kr:"그 제단은 신성하다."},{t:3,en:"They approached the altar.",kr:"그들은 제단으로 다가갔다."},{t:4,en:"The temple gave us an altar view.",kr:"그 사원은 우리에게 제단을 보여주었다."},{t:5,en:"We found the altar adorned.",kr:"우리는 그 제단이 장식된 것을 보았다."}]},
