  "altered": {img:"🔧", ex5:[{t:1,en:"The route was altered.",kr:"경로가 변경되었다."},{t:2,en:"The photo is altered.",kr:"그 사진은 변형되었다."},{t:3,en:"They altered the rules.",kr:"그들은 규칙을 바꿨다."},{t:4,en:"The edit gave us an altered version.",kr:"그 편집은 우리에게 변경된 버전을 주었다."},{t:5,en:"We found the image altered.",kr:"우리는 그 이미지가 변형된 것을 알았다."}]},
  "altering": {img:"🛠️", ex5:[{t:1,en:"They keep altering.",kr:"그들은 계속 바꾼다."},{t:2,en:"The act of altering is risky.",kr:"변경하는 일은 위험하다."},{t:3,en:"We are altering the plan.",kr:"우리는 그 계획을 바꾸고 있다."},{t:4,en:"The edit gave us altering options.",kr:"그 편집은 우리에게 변경 옵션을 주었다."},{t:5,en:"We found them altering the code.",kr:"우리는 그들이 코드를 변경하는 것을 알았다."}]},
  "alternate": {img:"🔀", ex5:[{t:1,en:"The patterns alternate.",kr:"무늬가 번갈아 나타난다."},{t:2,en:"The route is alternate.",kr:"그 경로는 대체 경로이다."},{t:3,en:"We alternate shifts.",kr:"우리는 교대 근무를 번갈아 한다."},{t:4,en:"The plan gave us an alternate path.",kr:"그 계획은 우리에게 대체 경로를 주었다."},{t:5,en:"We found an alternate route open.",kr:"우리는 대체 경로가 열린 것을 알았다."}]},
  "alternative": {img:"🔃", ex5:[{t:1,en:"An alternative exists.",kr:"대안이 존재한다."},{t:2,en:"The alternative is cheaper.",kr:"그 대안은 더 저렴하다."},{t:3,en:"We chose an alternative.",kr:"우리는 대안을 골랐다."},{t:4,en:"The plan gave us an alternative.",kr:"그 계획은 우리에게 대안을 주었다."},{t:5,en:"We found the alternative better.",kr:"우리는 그 대안이 더 낫다고 느꼈다."}]},
  "alternatively": {img:"↔️", ex5:[{t:1,en:"Alternatively, we wait.",kr:"아니면 우리는 기다린다."},{t:2,en:"The plan is, alternatively, simpler.",kr:"그 계획은 대안으로는 더 간단하다."},{t:3,en:"We could alternatively call.",kr:"우리는 대신 전화할 수도 있다."},{t:4,en:"It alternatively gave us a choice.",kr:"그것은 대안으로 우리에게 선택지를 주었다."},{t:5,en:"We found an alternatively cheaper way.",kr:"우리는 대안으로 더 저렴한 방법을 찾았다."}]},
  "alternatives": {img:"🔄", ex5:[{t:1,en:"Alternatives appeared.",kr:"대안들이 나타났다."},{t:2,en:"The alternatives are limited.",kr:"그 대안들은 제한적이다."},{t:3,en:"We weighed the alternatives.",kr:"우리는 대안들을 견주었다."},{t:4,en:"The team gave us alternatives.",kr:"그 팀은 우리에게 대안들을 주었다."},{t:5,en:"We found the alternatives viable.",kr:"우리는 그 대안들이 실행 가능하다고 보았다."}]},
  "although": {img:"🔁", ex5:[{t:1,en:"Although tired, they pressed on.",kr:"피곤했지만 그들은 계속했다."},{t:2,en:"It works, although slowly.",kr:"느리지만 그것은 작동한다."},{t:3,en:"We went, although it rained.",kr:"비가 왔지만 우리는 갔다."},{t:4,en:"Although small, it gave us hope.",kr:"작았지만 그것은 우리에게 희망을 주었다."},{t:5,en:"We found it fun, although hard.",kr:"어렵지만 우리는 그것이 재미있다고 느꼈다."}]},
  "altitude": {img:"⛰️", ex5:[{t:1,en:"The altitude rose.",kr:"고도가 높아졌다."},{t:2,en:"The altitude is high.",kr:"그 고도는 높다."},{t:3,en:"We checked the altitude.",kr:"우리는 고도를 확인했다."},{t:4,en:"The flight gave us a cruising altitude.",kr:"그 비행은 우리에게 순항 고도를 주었다."},{t:5,en:"We found the altitude dizzying.",kr:"우리는 그 고도가 아찔하다고 느꼈다."}]},
  "alto": {img:"🎶", ex5:[{t:1,en:"The alto sang.",kr:"알토가 노래했다."},{t:2,en:"Her voice is alto.",kr:"그녀의 목소리는 알토이다."},{t:3,en:"We need an alto.",kr:"우리는 알토가 필요하다."},{t:4,en:"The choir gave her an alto part.",kr:"합창단은 그녀에게 알토 파트를 주었다."},{t:5,en:"We found the alto rich.",kr:"우리는 그 알토가 풍부하다고 느꼈다."}]},
  "altogether": {img:"➕", ex5:[{t:1,en:"It stopped altogether.",kr:"그것은 완전히 멈췄다."},{t:2,en:"The cost is, altogether, high.",kr:"비용은 전부 합쳐 높다."},{t:3,en:"We dropped it altogether.",kr:"우리는 그것을 아예 그만뒀다."},{t:4,en:"The change gave us altogether new rules.",kr:"그 변화는 우리에게 완전히 새 규칙을 주었다."},{t:5,en:"We found the plan altogether flawed.",kr:"우리는 그 계획이 전적으로 결함이 있다고 보았다."}]},
  "altruism": {img:"💝", ex5:[{t:1,en:"Altruism inspires.",kr:"이타심은 감동을 준다."},{t:2,en:"Her altruism is rare.",kr:"그녀의 이타심은 드물다."},{t:3,en:"We admire altruism.",kr:"우리는 이타심을 존경한다."},{t:4,en:"The deed gave us altruism to follow.",kr:"그 행동은 우리에게 본받을 이타심을 보여주었다."},{t:5,en:"We found her altruism genuine.",kr:"우리는 그녀의 이타심이 진심임을 알았다."}]},
  "aluminum": {img:"🥫", ex5:[{t:1,en:"Aluminum is light.",kr:"알루미늄은 가볍다."},{t:2,en:"The can is aluminum.",kr:"그 캔은 알루미늄이다."},{t:3,en:"We recycle aluminum.",kr:"우리는 알루미늄을 재활용한다."},{t:4,en:"The plant gave us aluminum sheets.",kr:"그 공장은 우리에게 알루미늄 판을 주었다."},{t:5,en:"We found the aluminum sturdy.",kr:"우리는 그 알루미늄이 튼튼하다고 느꼈다."}]},
  "alumni": {img:"🎓", ex5:[{t:1,en:"Alumni gathered.",kr:"동문들이 모였다."},{t:2,en:"The alumni are proud.",kr:"그 동문들은 자랑스러워한다."},{t:3,en:"We contacted alumni.",kr:"우리는 동문들에게 연락했다."},{t:4,en:"The school gave alumni a reunion.",kr:"학교는 동문들에게 동창회를 마련해 주었다."},{t:5,en:"We found the alumni supportive.",kr:"우리는 그 동문들이 든든하다고 느꼈다."}]},
  "alumnus": {img:"🎓", ex5:[{t:1,en:"The alumnus returned.",kr:"그 졸업생이 돌아왔다."},{t:2,en:"The alumnus is famous.",kr:"그 졸업생은 유명하다."},{t:3,en:"We honored the alumnus.",kr:"우리는 그 졸업생을 기렸다."},{t:4,en:"The school gave the alumnus an award.",kr:"학교는 그 졸업생에게 상을 주었다."},{t:5,en:"We found the alumnus inspiring.",kr:"우리는 그 졸업생이 영감을 준다고 느꼈다."}]},
