  "amalgam": {img:"🔗", ex5:[{t:1,en:"The style is an amalgam of old and new.",kr:"그 양식은 옛것과 새것의 혼합이다."},{t:2,en:"Her art is an amalgam of forms.",kr:"그녀의 예술은 여러 형식의 융합이다."},{t:3,en:"The city is an amalgam of cultures.",kr:"그 도시는 여러 문화의 혼합체다."},{t:4,en:"The dish is an amalgam of flavors.",kr:"그 요리는 여러 맛의 조합이다."},{t:5,en:"His plan was an amalgam of ideas.",kr:"그의 계획은 여러 아이디어의 융합이었다."}]},
  "amalgamate": {img:"🔗", ex5:[{t:1,en:"The firms chose to amalgamate.",kr:"그 회사들은 합병하기로 했다."},{t:2,en:"They amalgamated two small teams.",kr:"그들은 작은 두 팀을 합쳤다."},{t:3,en:"The clubs will amalgamate next year.",kr:"그 클럽들은 내년에 통합될 것이다."},{t:4,en:"He sought to amalgamate the data.",kr:"그는 그 데이터를 한데 합치려 했다."},{t:5,en:"The towns amalgamated into one city.",kr:"그 마을들은 하나의 도시로 통합되었다."}]},
  "amalgamation": {img:"🔗", ex5:[{t:1,en:"The merger created a vast amalgamation of firms.",kr:"그 합병이 기업들의 거대한 통합체를 만들어냈다."},{t:2,en:"The style is an amalgamation of many traditions.",kr:"그 양식은 여러 전통의 융합이다."},{t:3,en:"The amalgamation of the two clubs was announced.",kr:"두 클럽의 합병이 발표되었다."},{t:4,en:"The dish is an amalgamation of local flavors.",kr:"그 요리는 지역 맛들의 결합이다."},{t:5,en:"The report described the amalgamation of departments.",kr:"그 보고서가 부서들의 통합을 설명했다."}]},
  "amass": {img:"💰", ex5:[{t:1,en:"He amassed a large fortune.",kr:"그는 막대한 재산을 모았다."},{t:2,en:"She amassed a huge book collection.",kr:"그녀는 엄청난 책 수집품을 모았다."},{t:3,en:"They amassed enough food for winter.",kr:"그들은 겨울에 쓸 충분한 음식을 비축했다."},{t:4,en:"The team amassed many wins.",kr:"그 팀은 많은 승리를 쌓았다."},{t:5,en:"Over years he amassed great knowledge.",kr:"여러 해에 걸쳐 그는 방대한 지식을 쌓았다."}]},
