  "amazed": {img:"😲", ex5:[{t:1,en:"The crowd was amazed.",kr:"관중이 놀랐다."},{t:2,en:"She looked amazed.",kr:"그녀는 놀란 표정이었다."},{t:3,en:"The trick amazed us.",kr:"그 묘기가 우리를 놀라게 했다."},{t:4,en:"The view gave us an amazed gasp.",kr:"그 경치는 우리에게 놀란 탄성을 자아냈다."},{t:5,en:"We found ourselves amazed.",kr:"우리는 스스로 놀라고 있음을 알았다."}]},
  "amazement": {img:"😮", ex5:[{t:1,en:"Amazement filled the room.",kr:"놀라움이 방을 가득 채웠다."},{t:2,en:"Her amazement was clear.",kr:"그녀의 놀라움은 분명했다."},{t:3,en:"We watched in amazement.",kr:"우리는 놀라며 지켜보았다."},{t:4,en:"The feat gave us amazement.",kr:"그 위업은 우리에게 놀라움을 안겼다."},{t:5,en:"We found the amazement genuine.",kr:"우리는 그 놀라움이 진심임을 알았다."}]},
  "amazing": {img:"🤩", ex5:[{t:1,en:"The view is amazing.",kr:"그 경치는 놀랍다."},{t:2,en:"The food is amazing.",kr:"그 음식은 훌륭하다."},{t:3,en:"We had an amazing time.",kr:"우리는 멋진 시간을 보냈다."},{t:4,en:"The trip gave us amazing memories.",kr:"그 여행은 우리에게 놀라운 추억을 안겼다."},{t:5,en:"We found the show amazing.",kr:"우리는 그 공연이 놀랍다고 느꼈다."}]},
