  "ambiguous": {img:"🤷", ex5:[{t:1,en:"The answer is ambiguous.",kr:"그 답은 모호하다."},{t:2,en:"The wording is ambiguous.",kr:"그 표현은 애매하다."},{t:3,en:"We clarified the ambiguous term.",kr:"우리는 그 모호한 용어를 명확히 했다."},{t:4,en:"The clause gave us an ambiguous rule.",kr:"그 조항은 우리에게 모호한 규칙을 주었다."},{t:5,en:"We found the message ambiguous.",kr:"우리는 그 메시지가 모호하다고 느꼈다."}]},
  "ambit": {img:"⭕", ex5:[{t:1,en:"The case falls within the court's ambit.",kr:"그 사건은 법원의 관할 범위 안에 든다."},{t:2,en:"This topic lies outside our ambit.",kr:"이 주제는 우리 영역 밖에 있다."},{t:3,en:"The rule has a very broad ambit.",kr:"그 규정은 매우 넓은 적용 범위를 지닌다."},{t:4,en:"Such issues are beyond the ambit of the law.",kr:"그런 문제는 그 법의 범위를 벗어난다."},{t:5,en:"Their work expanded the ambit of research.",kr:"그들의 작업은 연구의 범위를 넓혔다."}]},
  "ambition": {img:"🚀", ex5:[{t:1,en:"Ambition drives her.",kr:"야망이 그녀를 움직인다."},{t:2,en:"His ambition is huge.",kr:"그의 야망은 크다."},{t:3,en:"We admire her ambition.",kr:"우리는 그녀의 야망을 존경한다."},{t:4,en:"The goal gave him ambition.",kr:"그 목표는 그에게 야망을 주었다."},{t:5,en:"We found his ambition bold.",kr:"우리는 그의 야망이 대담하다고 느꼈다."}]},
  "ambitions": {img:"🎯", ex5:[{t:1,en:"Ambitions grew.",kr:"야망이 커졌다."},{t:2,en:"Her ambitions are clear.",kr:"그녀의 야망은 분명하다."},{t:3,en:"We shared our ambitions.",kr:"우리는 우리의 야망을 나눴다."},{t:4,en:"Youth gave us big ambitions.",kr:"젊음은 우리에게 큰 야망을 주었다."},{t:5,en:"We found their ambitions inspiring.",kr:"우리는 그들의 야망이 영감을 준다고 느꼈다."}]},
  "ambitious": {img:"🧗‍♂️", ex5:[{t:1,en:"The plan is ambitious.",kr:"그 계획은 야심차다."},{t:2,en:"She is ambitious.",kr:"그녀는 야심차다."},{t:3,en:"We set an ambitious goal.",kr:"우리는 야심찬 목표를 세웠다."},{t:4,en:"The project gave us an ambitious target.",kr:"그 프로젝트는 우리에게 야심찬 목표를 주었다."},{t:5,en:"We found the plan ambitious.",kr:"우리는 그 계획이 야심차다고 느꼈다."}]},
  "ambivalence": {img:"😕", ex5:[{t:1,en:"She felt deep ambivalence about the move.",kr:"그녀는 이사에 대해 깊은 양가감정을 느꼈다."},{t:2,en:"His ambivalence delayed the decision.",kr:"그의 망설임이 결정을 늦췄다."},{t:3,en:"The ambivalence in his voice was clear.",kr:"그의 목소리에 담긴 양가감정이 뚜렷했다."},{t:4,en:"They sensed her ambivalence toward the plan.",kr:"그들은 그 계획에 대한 그녀의 양가감정을 감지했다."},{t:5,en:"My ambivalence about the job confused everyone.",kr:"그 일자리에 대한 나의 양가감정이 모두를 헷갈리게 했다."}]},
  "amble": {img:"🐢", ex5:[{t:1,en:"They ambled along the beach at dusk.",kr:"그들은 해질녘 해변을 느긋이 거닐었다."},{t:2,en:"The old horse ambled down the road.",kr:"늙은 말이 길을 따라 느릿느릿 걸었다."},{t:3,en:"She ambled home after the show.",kr:"그녀는 공연 후 집으로 어슬렁어슬렁 갔다."},{t:4,en:"He ambled through the park.",kr:"그는 공원을 한가로이 거닐었다."},{t:5,en:"We ambled with no rush at all.",kr:"우리는 전혀 서두르지 않고 느긋이 걸었다."}]},
  "ambulance": {img:"🚑", ex5:[{t:1,en:"The ambulance raced.",kr:"구급차가 달렸다."},{t:2,en:"The ambulance is fast.",kr:"그 구급차는 빠르다."},{t:3,en:"We called an ambulance.",kr:"우리는 구급차를 불렀다."},{t:4,en:"The crew gave the patient an ambulance ride.",kr:"구급대원들은 환자를 구급차로 이송했다."},{t:5,en:"We found the ambulance ready.",kr:"우리는 그 구급차가 대기 중임을 알았다."}]},
  "ambush": {img:"🗡️", ex5:[{t:1,en:"The ambush struck.",kr:"매복 공격이 가해졌다."},{t:2,en:"The ambush was sudden.",kr:"그 매복은 갑작스러웠다."},{t:3,en:"They set an ambush.",kr:"그들은 매복을 펼쳤다."},{t:4,en:"The enemy gave us an ambush.",kr:"적은 우리에게 매복 공격을 가했다."},{t:5,en:"We found the ambush well planned.",kr:"우리는 그 매복이 치밀했다고 보았다."}]},
  "ameliorate": {img:"🩹", ex5:[{t:1,en:"The new law helped ameliorate poverty.",kr:"새 법은 빈곤을 개선하는 데 도움이 됐다."},{t:2,en:"They worked to ameliorate the harm.",kr:"그들은 피해를 완화하려 애썼다."},{t:3,en:"Rest helped ameliorate his pain.",kr:"휴식은 그의 통증을 덜어주는 데 도움이 됐다."},{t:4,en:"Steps were taken to ameliorate it.",kr:"그것을 개선하기 위한 조치가 취해졌다."},{t:5,en:"Aid can ameliorate the worst effects.",kr:"원조는 최악의 영향을 완화할 수 있다."}]},
  "amelioration": {img:"📈", ex5:[{t:1,en:"The reforms led to a clear amelioration of conditions.",kr:"그 개혁이 여건의 뚜렷한 개선으로 이어졌다."},{t:2,en:"Doctors noted an amelioration of her symptoms.",kr:"의사들이 그녀의 증상 호전을 확인했다."},{t:3,en:"The project aimed at the amelioration of poverty.",kr:"그 사업은 빈곤의 완화를 목표로 했다."},{t:4,en:"Any amelioration would require steady effort.",kr:"어떤 개선이든 꾸준한 노력이 필요할 것이다."},{t:5,en:"The amelioration of the soil improved the crops.",kr:"토양의 개량이 작물을 더 좋게 했다."}]},
  "amen": {img:"🙏", ex5:[{t:1,en:"They said amen.",kr:"그들은 아멘이라고 했다."},{t:2,en:"The prayer ends amen.",kr:"그 기도는 아멘으로 끝난다."},{t:3,en:"We whispered amen.",kr:"우리는 아멘이라고 속삭였다."},{t:4,en:"The chant gave us an amen.",kr:"그 성가는 우리에게 아멘을 이끌었다."},{t:5,en:"We found the amen heartfelt.",kr:"우리는 그 아멘이 진심임을 느꼈다."}]},
  "amenable": {img:"🙆", ex5:[{t:1,en:"She was amenable to a fair compromise.",kr:"그녀는 공정한 타협에 순순히 따랐다."},{t:2,en:"The boss is amenable to new ideas.",kr:"그 상사는 새로운 생각을 잘 받아들인다."},{t:3,en:"Most staff were amenable to the change.",kr:"대부분의 직원은 그 변화에 호의적이었다."},{t:4,en:"The problem is amenable to a simple fix.",kr:"그 문제는 간단한 해결에 잘 들어맞는다."},{t:5,en:"He proved amenable to gentle persuasion.",kr:"그는 부드러운 설득에 순응하는 모습을 보였다."}]},
