  "americans": {img:"🇺🇸", ex5:[{t:1,en:"Americans voted.",kr:"미국인들이 투표했다."},{t:2,en:"The Americans are diverse.",kr:"그 미국인들은 다양하다."},{t:3,en:"We surveyed Americans.",kr:"우리는 미국인들을 조사했다."},{t:4,en:"The poll gave us Americans' views.",kr:"그 여론조사는 우리에게 미국인들의 견해를 주었다."},{t:5,en:"We found the Americans welcoming.",kr:"우리는 그 미국인들이 친절하다고 느꼈다."}]},
  "amethyst": {img:"💜", ex5:[{t:1,en:"The ring held a deep purple amethyst.",kr:"그 반지에는 짙은 보라색 자수정이 박혀 있었다."},{t:2,en:"An amethyst glowed in the lamplight.",kr:"자수정이 등불 빛에 은은히 빛났다."},{t:3,en:"She wore amethyst earrings to the party.",kr:"그녀는 파티에 자수정 귀걸이를 했다."},{t:4,en:"The amethyst is a violet form of quartz.",kr:"자수정은 보라색을 띤 석영의 한 형태다."},{t:5,en:"A raw amethyst sparkled in the rock.",kr:"가공하지 않은 자수정이 바위 속에서 반짝였다."}]},
  "amiable": {img:"🙂", ex5:[{t:1,en:"She has an amiable personality.",kr:"그녀는 상냥한 성격을 지녔다."},{t:2,en:"The two had an amiable chat.",kr:"두 사람은 다정한 대화를 나눴다."},{t:3,en:"He was amiable to everyone he met.",kr:"그는 만나는 모든 이에게 상냥했다."},{t:4,en:"They reached an amiable agreement.",kr:"그들은 원만한 합의에 이르렀다."},{t:5,en:"Her amiable smile warmed the room.",kr:"그녀의 상냥한 미소가 방을 따뜻하게 했다."}]},
  "amiably": {img:"😊", ex5:[{t:1,en:"They chatted amiably over coffee.",kr:"그들은 커피를 마시며 다정하게 담소했다."},{t:2,en:"He greeted the newcomer amiably.",kr:"그는 새로 온 사람을 상냥하게 맞이했다."},{t:3,en:"She smiled amiably at the guests.",kr:"그녀는 손님들에게 상냥하게 미소 지었다."},{t:4,en:"The two rivals parted amiably.",kr:"두 경쟁자는 원만하게 헤어졌다."},{t:5,en:"He answered the questions amiably.",kr:"그는 그 질문들에 상냥하게 답했다."}]},
  "amicable": {img:"🤝", ex5:[{t:1,en:"The split was amicable.",kr:"그 결별은 원만했다."},{t:2,en:"The talks are amicable.",kr:"그 협상은 우호적이다."},{t:3,en:"We reached an amicable deal.",kr:"우리는 원만한 합의에 이르렀다."},{t:4,en:"The meeting gave us an amicable mood.",kr:"그 회의는 우리에게 화기애애한 분위기를 주었다."},{t:5,en:"We found the parting amicable.",kr:"우리는 그 이별이 원만하다고 느꼈다."}]},
  "amid": {img:"🔛", ex5:[{t:1,en:"She stayed calm amid chaos.",kr:"그녀는 혼란 속에서도 침착했다."},{t:2,en:"The house stands amid trees.",kr:"그 집은 나무들 가운데 서 있다."},{t:3,en:"We worked amid noise.",kr:"우리는 소음 속에서 일했다."},{t:4,en:"Amid the crowd, she gave me a sign.",kr:"군중 속에서 그녀는 나에게 신호를 보냈다."},{t:5,en:"We found peace amid the storm.",kr:"우리는 폭풍 속에서 평온을 찾았다."}]},
  "amidst": {img:"🌫️", ex5:[{t:1,en:"They smiled amidst tears.",kr:"그들은 눈물 속에서 미소 지었다."},{t:2,en:"The flower bloomed amidst rocks.",kr:"그 꽃은 바위들 사이에서 피었다."},{t:3,en:"We stood amidst the ruins.",kr:"우리는 폐허 가운데 섰다."},{t:4,en:"Amidst doubt, hope gave us strength.",kr:"의심 속에서 희망이 우리에게 힘을 주었다."},{t:5,en:"We found calm amidst the rush.",kr:"우리는 분주함 속에서 평온을 찾았다."}]},
  "amino": {img:"🧬", ex5:[{t:1,en:"Amino acids build proteins.",kr:"아미노산은 단백질을 만든다."},{t:2,en:"The amino acid is essential.",kr:"그 아미노산은 필수적이다."},{t:3,en:"We studied amino acids.",kr:"우리는 아미노산을 공부했다."},{t:4,en:"The class gave us amino acid charts.",kr:"그 수업은 우리에게 아미노산 도표를 주었다."},{t:5,en:"We found the amino acid vital.",kr:"우리는 그 아미노산이 필수적임을 알았다."}]},
  "amity": {img:"🤝", ex5:[{t:1,en:"The two nations lived in lasting amity.",kr:"두 나라는 오래 지속되는 친선 속에 지냈다."},{t:2,en:"The treaty restored amity between them.",kr:"그 조약은 그들 사이의 우호를 회복시켰다."},{t:3,en:"Neighbors kept an easy amity for years.",kr:"이웃들은 여러 해 동안 편안한 우정을 지켰다."},{t:4,en:"They parted in amity, with no hard feelings.",kr:"그들은 앙금 없이 화목하게 헤어졌다."},{t:5,en:"The festival celebrates regional amity.",kr:"그 축제는 지역 간 친선을 기린다."}]},
  "ammonia": {img:"🧴", ex5:[{t:1,en:"Ammonia smells sharp.",kr:"암모니아는 톡 쏘는 냄새가 난다."},{t:2,en:"The ammonia is strong.",kr:"그 암모니아는 강하다."},{t:3,en:"We diluted the ammonia.",kr:"우리는 암모니아를 희석했다."},{t:4,en:"The lab gave us ammonia samples.",kr:"그 실험실은 우리에게 암모니아 시료를 주었다."},{t:5,en:"We found the ammonia pungent.",kr:"우리는 그 암모니아가 자극적이라고 느꼈다."}]},
