  "amongst": {img:"👫", ex5:[{t:1,en:"They mingled amongst guests.",kr:"그들은 손님들 사이에 섞였다."},{t:2,en:"The view is best amongst the hills.",kr:"그 경치는 언덕들 사이에서 가장 좋다."},{t:3,en:"We walked amongst the trees.",kr:"우리는 나무들 사이를 걸었다."},{t:4,en:"Amongst peers, she gave a speech.",kr:"동료들 사이에서 그녀는 연설을 했다."},{t:5,en:"We found unity amongst the team.",kr:"우리는 팀 안에서 단결을 발견했다."}]},
  "amorphous": {img:"☁️", ex5:[{t:1,en:"The blob had an amorphous shape.",kr:"그 덩어리는 일정한 형태가 없었다."},{t:2,en:"Their plan was vague and amorphous.",kr:"그들의 계획은 막연하고 형태가 없었다."},{t:3,en:"The mist formed an amorphous mass.",kr:"안개가 형체 없는 덩어리를 이뤘다."},{t:4,en:"His ideas remained amorphous.",kr:"그의 생각은 여전히 막연했다."},{t:5,en:"The group was loose and amorphous.",kr:"그 모임은 느슨하고 모호했다."}]},
  "amortize": {img:"💵", ex5:[{t:1,en:"They will amortize the loan over ten years.",kr:"그들은 그 대출을 십 년에 걸쳐 분할 상환할 것이다."},{t:2,en:"The company amortizes the cost of the equipment.",kr:"그 회사는 장비 비용을 감가상각으로 분산한다."},{t:3,en:"You can amortize the expense across the project.",kr:"그 비용을 프로젝트 전체에 걸쳐 분산 처리할 수 있다."},{t:4,en:"The mortgage is amortized in monthly payments.",kr:"그 주택 담보 대출은 매월 분할 상환된다."},{t:5,en:"They amortize software costs over its useful life.",kr:"그들은 소프트웨어 비용을 사용 기간에 걸쳐 상각한다."}]},
  "amount": {img:"💲", ex5:[{t:1,en:"The amount grew.",kr:"금액이 늘었다."},{t:2,en:"The amount is large.",kr:"그 양은 많다."},{t:3,en:"We checked the amount.",kr:"우리는 그 액수를 확인했다."},{t:4,en:"The bill gave us the amount due.",kr:"그 청구서는 우리에게 낼 금액을 알려주었다."},{t:5,en:"We found the amount correct.",kr:"우리는 그 금액이 맞다고 확인했다."}]},
  "amounted": {img:"🧾", ex5:[{t:1,en:"The total amounted high.",kr:"합계가 높게 나왔다."},{t:2,en:"The cost amounted to much.",kr:"비용이 상당했다."},{t:3,en:"The fees amounted to a lot.",kr:"수수료가 많이 나왔다."},{t:4,en:"The errors amounted us trouble.",kr:"그 실수들은 우리에게 골칫거리를 안겼다."},{t:5,en:"We found the debt amounted to thousands.",kr:"우리는 빚이 수천에 이른 것을 알았다."}]},
  "amounts": {img:"📊", ex5:[{t:1,en:"Amounts vary.",kr:"액수는 다양하다."},{t:2,en:"The amounts are small.",kr:"그 양들은 적다."},{t:3,en:"We compared amounts.",kr:"우리는 액수를 비교했다."},{t:4,en:"The recipe gave us exact amounts.",kr:"그 조리법은 우리에게 정확한 분량을 주었다."},{t:5,en:"We found the amounts uneven.",kr:"우리는 그 양들이 고르지 않음을 알았다."}]},
  "amp": {img:"🔊", ex5:[{t:1,en:"The amp buzzed.",kr:"앰프가 윙윙거렸다."},{t:2,en:"The amp is powerful.",kr:"그 앰프는 출력이 세다."},{t:3,en:"We plugged in the amp.",kr:"우리는 앰프를 연결했다."},{t:4,en:"The band gave us a new amp.",kr:"그 밴드는 우리에게 새 앰프를 주었다."},{t:5,en:"We found the amp loud.",kr:"우리는 그 앰프가 시끄럽다고 느꼈다."}]},
  "ampere": {img:"⚡", ex5:[{t:1,en:"The current was measured in ampere units.",kr:"전류는 암페어 단위로 측정되었다."},{t:2,en:"This circuit draws about two ampere.",kr:"이 회로는 약 2암페어를 끌어 쓴다."},{t:3,en:"An ampere measures the flow of electric charge.",kr:"암페어는 전하의 흐름을 측정한다."},{t:4,en:"The fuse blows above ten ampere.",kr:"그 퓨즈는 10암페어를 넘으면 끊어진다."},{t:5,en:"The meter showed a reading of one ampere.",kr:"계측기는 1암페어 수치를 보여주었다."}]},
  "ample": {img:"🫗", ex5:[{t:1,en:"There is ample room.",kr:"공간이 넉넉하다."},{t:2,en:"The supply is ample.",kr:"공급이 충분하다."},{t:3,en:"We have ample time.",kr:"우리는 시간이 충분하다."},{t:4,en:"The fund gave us ample support.",kr:"그 기금은 우리에게 충분한 지원을 주었다."},{t:5,en:"We found the space ample.",kr:"우리는 그 공간이 넉넉하다고 느꼈다."}]},
  "amplification": {img:"🔊", ex5:[{t:1,en:"The speech needed amplification to reach the back.",kr:"그 연설은 뒤쪽까지 닿으려면 증폭이 필요했다."},{t:2,en:"The amplification of the signal improved clarity.",kr:"신호의 증폭이 선명도를 높였다."},{t:3,en:"Social media allows rapid amplification of rumors.",kr:"소셜 미디어는 소문의 빠른 확산을 가능하게 한다."},{t:4,en:"The amplification distorted the sound slightly.",kr:"그 증폭이 소리를 약간 왜곡했다."},{t:5,en:"The lab studied the amplification of DNA.",kr:"그 실험실은 DNA의 증폭을 연구했다."}]},
