  "aquifer": {img:"💧", ex5:[{t:1,en:"The town draws water from an underground aquifer.",kr:"그 마을은 지하 대수층에서 물을 끌어온다."},{t:2,en:"Over-pumping can drain an aquifer.",kr:"과도한 양수는 대수층을 고갈시킬 수 있다."},{t:3,en:"The aquifer supplies most of the region's water.",kr:"그 대수층은 그 지역 물의 대부분을 공급한다."},{t:4,en:"Pollution threatened the local aquifer.",kr:"오염이 지역 대수층을 위협했다."},{t:5,en:"Rain slowly replenishes the aquifer.",kr:"비가 천천히 대수층을 다시 채운다."}]},
  "arab": {img:"🕌", ex5:[{t:1,en:"The Arab world is vast.",kr:"아랍 세계는 광대하다."},{t:2,en:"The trader is Arab.",kr:"그 상인은 아랍인이다."},{t:3,en:"We met an Arab scholar.",kr:"우리는 아랍 학자를 만났다."},{t:4,en:"The host gave us Arab coffee.",kr:"주인은 우리에게 아랍 커피를 대접했다."},{t:5,en:"We found the Arab market lively.",kr:"우리는 그 아랍 시장이 활기차다고 느꼈다."}]},
  "arabia": {img:"🏜️", ex5:[{t:1,en:"Arabia stretches wide.",kr:"아라비아는 넓게 펼쳐진다."},{t:2,en:"Arabia is arid.",kr:"아라비아는 건조하다."},{t:3,en:"We crossed Arabia.",kr:"우리는 아라비아를 횡단했다."},{t:4,en:"The trip gave us Arabia deserts.",kr:"그 여행은 우리에게 아라비아 사막을 보여주었다."},{t:5,en:"We found Arabia stunning.",kr:"우리는 아라비아가 멋지다고 느꼈다."}]},
  "arabian": {img:"🐪", ex5:[{t:1,en:"The Arabian horse ran.",kr:"아라비아 말이 달렸다."},{t:2,en:"The night is Arabian.",kr:"그 밤은 아라비아풍이다."},{t:3,en:"We rode an Arabian camel.",kr:"우리는 아라비아 낙타를 탔다."},{t:4,en:"The tale gave us Arabian nights.",kr:"그 이야기는 우리에게 아라비안나이트를 들려주었다."},{t:5,en:"We found the Arabian desert vast.",kr:"우리는 그 아라비아 사막이 광대하다고 느꼈다."}]},
  "arbiter": {img:"⚖️", ex5:[{t:1,en:"She became the arbiter of the dispute.",kr:"그녀는 그 분쟁의 중재자가 되었다."},{t:2,en:"He is the final arbiter of taste here.",kr:"그는 이곳 취향의 최종 결정권자다."},{t:3,en:"A neutral arbiter settled the matter.",kr:"중립적인 중재자가 그 문제를 해결했다."},{t:4,en:"The court acts as an arbiter of law.",kr:"법원은 법의 심판자 역할을 한다."},{t:5,en:"They chose a fair arbiter.",kr:"그들은 공정한 중재자를 골랐다."}]},
  "arbitrage": {img:"📈", ex5:[{t:1,en:"Traders profit from arbitrage between markets.",kr:"거래자들은 시장 간 차익 거래로 이익을 본다."},{t:2,en:"Arbitrage exploits small price differences.",kr:"차익 거래는 작은 가격 차이를 이용한다."},{t:3,en:"He made a fortune through currency arbitrage.",kr:"그는 환율 차익 거래로 큰돈을 벌었다."},{t:4,en:"Fast computers enable instant arbitrage.",kr:"빠른 컴퓨터는 즉각적인 차익 거래를 가능하게 한다."},{t:5,en:"Arbitrage opportunities vanish quickly.",kr:"차익 거래 기회는 빠르게 사라진다."}]},
  "arbitrary": {img:"🎲", ex5:[{t:1,en:"The rule seems arbitrary.",kr:"그 규칙은 자의적으로 보인다."},{t:2,en:"The choice is arbitrary.",kr:"그 선택은 임의적이다."},{t:3,en:"We rejected the arbitrary limit.",kr:"우리는 그 자의적인 제한을 거부했다."},{t:4,en:"The judge gave an arbitrary ruling.",kr:"그 판사는 자의적인 판결을 내렸다."},{t:5,en:"We found the decision arbitrary.",kr:"우리는 그 결정이 자의적이라고 보았다."}]},
  "arbitrate": {img:"⚖️", ex5:[{t:1,en:"A judge arbitrated the dispute.",kr:"한 판사가 그 분쟁을 중재했다."},{t:2,en:"They asked her to arbitrate the disagreement.",kr:"그들은 그녀에게 그 갈등의 중재를 부탁했다."},{t:3,en:"He arbitrated fairly between the two sides.",kr:"그는 양측 사이를 공정하게 중재했다."},{t:4,en:"The board arbitrated the contract conflict.",kr:"이사회가 그 계약 갈등을 중재했다."},{t:5,en:"A neutral party arbitrated the case.",kr:"중립적인 측이 그 사건을 중재했다."}]},
  "arbitration": {img:"⚖️", ex5:[{t:1,en:"Arbitration settled it.",kr:"중재가 그것을 해결했다."},{t:2,en:"The arbitration is binding.",kr:"그 중재는 구속력이 있다."},{t:3,en:"We chose arbitration.",kr:"우리는 중재를 택했다."},{t:4,en:"The clause gave us arbitration rights.",kr:"그 조항은 우리에게 중재 권리를 주었다."},{t:5,en:"We found the arbitration fair.",kr:"우리는 그 중재가 공정하다고 보았다."}]},
  "arbitrator": {img:"⚖️", ex5:[{t:1,en:"The arbitrator settled the dispute fairly.",kr:"그 중재인이 분쟁을 공정하게 해결했다."},{t:2,en:"Both sides agreed to accept the arbitrator's ruling.",kr:"양측은 중재인의 결정을 받아들이기로 합의했다."},{t:3,en:"An independent arbitrator reviewed the case.",kr:"독립적인 중재인이 그 사건을 검토했다."},{t:4,en:"The arbitrator listened to both arguments.",kr:"그 중재인은 양쪽 주장을 모두 들었다."},{t:5,en:"They called in an arbitrator to end the deadlock.",kr:"그들은 교착 상태를 끝내려고 중재인을 불렀다."}]},
  "arboreal": {img:"🌳", ex5:[{t:1,en:"Monkeys lead a mostly arboreal life.",kr:"원숭이들은 대체로 나무 위에서 사는 생활을 한다."},{t:2,en:"The sloth is a slow arboreal animal.",kr:"나무늘보는 느린 수상(樹上) 동물이다."},{t:3,en:"Many arboreal birds nest high in trees.",kr:"많은 수상성 새들은 나무 높이 둥지를 튼다."},{t:4,en:"Arboreal species depend on dense forests.",kr:"나무 위에 사는 종들은 울창한 숲에 의존한다."},{t:5,en:"The frog has an arboreal habitat.",kr:"그 개구리는 나무 위 서식지를 갖는다."}]},
