  "bandanna": {img:"🧣", ex5:[{t:1,en:"He tied a bandanna around his neck.",kr:"그는 목에 반다나를 둘렀다."},{t:2,en:"The hiker wore a bandanna to block the dust.",kr:"그 등산객은 먼지를 막으려고 반다나를 둘렀다."},{t:3,en:"She folded the bandanna into a headband.",kr:"그녀는 반다나를 접어 머리띠로 만들었다."},{t:4,en:"A red bandanna hung from his pocket.",kr:"빨간 반다나가 그의 주머니에서 삐져나와 있었다."},{t:5,en:"The dog wore a tiny bandanna.",kr:"그 개는 작은 반다나를 두르고 있었다."}]},
  "bands": {img:"🎶", ex5:[{t:1,en:"Bands performed.",kr:"밴드들이 공연했다."},{t:2,en:"The bands are diverse.",kr:"그 밴드들은 다양하다."},{t:3,en:"We booked two bands.",kr:"우리는 밴드 둘을 섭외했다."},{t:4,en:"The festival gave us bands to enjoy.",kr:"그 축제는 우리에게 즐길 밴드들을 주었다."},{t:5,en:"We found the bands lively.",kr:"우리는 그 밴드들이 활기차다고 느꼈다."}]},
  "bandwidth": {img:"📶", ex5:[{t:1,en:"Bandwidth dropped.",kr:"대역폭이 떨어졌다."},{t:2,en:"The bandwidth is high.",kr:"그 대역폭은 높다."},{t:3,en:"We upgraded the bandwidth.",kr:"우리는 대역폭을 늘렸다."},{t:4,en:"The plan gave us more bandwidth.",kr:"그 요금제는 우리에게 더 많은 대역폭을 주었다."},{t:5,en:"We found the bandwidth low.",kr:"우리는 그 대역폭이 낮음을 알았다."}]},
  "baneful": {img:"☠️", ex5:[{t:1,en:"Greed had a baneful effect on the town.",kr:"탐욕은 그 마을에 해로운 영향을 끼쳤다."},{t:2,en:"The baneful rumor ruined his name.",kr:"그 해로운 소문이 그의 명예를 망쳤다."},{t:3,en:"They feared the baneful power of the curse.",kr:"그들은 그 저주의 해로운 힘을 두려워했다."},{t:4,en:"Pollution has a baneful impact on health.",kr:"오염은 건강에 해로운 영향을 미친다."},{t:5,en:"Her baneful influence spread quietly.",kr:"그녀의 해로운 영향력은 조용히 퍼졌다."}]},
  "bang": {img:"💥", ex5:[{t:1,en:"The door went bang.",kr:"문이 쾅 닫혔다."},{t:2,en:"The bang was loud.",kr:"그 쾅 소리는 컸다."},{t:3,en:"We heard a bang.",kr:"우리는 쾅 소리를 들었다."},{t:4,en:"The shot gave us a loud bang.",kr:"그 발사는 우리에게 큰 폭음을 안겼다."},{t:5,en:"We found the bang startling.",kr:"우리는 그 폭음이 놀랍다고 느꼈다."}]},
  "banish": {img:"🚪", ex5:[{t:1,en:"The king banished the rebel from the land.",kr:"왕은 그 반역자를 그 땅에서 추방했다."},{t:2,en:"She banished all doubt from her mind.",kr:"그녀는 마음에서 모든 의심을 몰아냈다."},{t:3,en:"They banished him to a distant island.",kr:"그들은 그를 먼 섬으로 추방했다."},{t:4,en:"A warm fire banished the cold.",kr:"따뜻한 불이 추위를 몰아냈다."},{t:5,en:"He tried to banish the sad thoughts.",kr:"그는 슬픈 생각들을 떨쳐 내려 했다."}]},
  "banishment": {img:"🚪", ex5:[{t:1,en:"The king ordered the rebel's banishment.",kr:"왕이 그 반역자의 추방을 명령했다."},{t:2,en:"Banishment was a harsh punishment in old times.",kr:"추방은 옛 시절에 가혹한 형벌이었다."},{t:3,en:"His banishment lasted for ten long years.",kr:"그의 추방은 길고 긴 십 년 동안 이어졌다."},{t:4,en:"She accepted banishment rather than betray her friends.",kr:"그녀는 친구들을 배신하느니 추방을 받아들였다."},{t:5,en:"The banishment ended when the new ruler took power.",kr:"새 통치자가 권력을 잡자 그 추방이 끝났다."}]},
