  "breezy": {img:"🍃", ex5:[{t:1,en:"It was a bright and breezy morning.",kr:"화창하고 산들바람 부는 아침이었다."},{t:2,en:"She has a breezy, easy manner.",kr:"그녀는 가볍고 편안한 태도를 지녔다."},{t:3,en:"The breezy beach felt cool.",kr:"산들바람 부는 해변은 시원했다."},{t:4,en:"He gave a breezy reply.",kr:"그는 가볍게 툭 답했다."},{t:5,en:"A breezy day is good for sailing.",kr:"바람 부는 날은 항해하기 좋다."}]},
  "brethren": {img:"🤝", ex5:[{t:1,en:"He addressed his brethren warmly.",kr:"그는 형제들에게 따뜻하게 말했다."},{t:2,en:"The brethren gathered to pray.",kr:"형제들이 기도하러 모였다."},{t:3,en:"She helped her brethren in need.",kr:"그녀는 어려운 동지들을 도왔다."},{t:4,en:"The brethren shared all they had.",kr:"형제들은 가진 모든 것을 나눴다."},{t:5,en:"He called on his brethren for unity.",kr:"그는 형제들에게 단결을 호소했다."}]},
  "brew": {img:"☕", ex5:[{t:1,en:"Coffee brews.",kr:"커피가 내려진다."},{t:2,en:"The tea is brewing.",kr:"차가 우러나고 있다."},{t:3,en:"We brew coffee.",kr:"우리는 커피를 내린다."},{t:4,en:"The cafe gave us a fresh brew.",kr:"그 카페는 우리에게 갓 내린 커피를 주었다."},{t:5,en:"We brew the tea strong.",kr:"우리는 차를 진하게 우린다."}]},
  "brick": {img:"🧱", ex5:[{t:1,en:"The brick fell.",kr:"벽돌이 떨어졌다."},{t:2,en:"The brick is red.",kr:"그 벽돌은 빨갛다."},{t:3,en:"We laid the brick.",kr:"우리는 벽돌을 쌓았다."},{t:4,en:"The yard gave us bricks.",kr:"그 야적장은 우리에게 벽돌을 주었다."},{t:5,en:"We found the brick chipped.",kr:"우리는 그 벽돌이 깨진 것을 알았다."}]},
  "bricklayer": {img:"🧱", ex5:[{t:1,en:"The bricklayer built the wall row by row.",kr:"그 벽돌공은 벽을 한 줄씩 쌓아 올렸다."},{t:2,en:"A skilled bricklayer works quickly and neatly.",kr:"숙련된 벽돌공은 빠르고 깔끔하게 일한다."},{t:3,en:"The bricklayer spread mortar with a trowel.",kr:"그 벽돌공이 흙손으로 모르타르를 발랐다."},{t:4,en:"They hired a bricklayer to repair the chimney.",kr:"그들은 굴뚝을 수리하려고 벽돌공을 고용했다."},{t:5,en:"The bricklayer checked each row with a level.",kr:"그 벽돌공은 수평기로 각 줄을 확인했다."}]},
  "bricks": {img:"🧱", ex5:[{t:1,en:"Bricks stacked up.",kr:"벽돌들이 쌓였다."},{t:2,en:"The bricks are heavy.",kr:"그 벽돌들은 무겁다."},{t:3,en:"We carried the bricks.",kr:"우리는 벽돌들을 날랐다."},{t:4,en:"The site gave us bricks.",kr:"그 현장은 우리에게 벽돌들을 공급했다."},{t:5,en:"We found the bricks sturdy.",kr:"우리는 그 벽돌들이 튼튼하다고 느꼈다."}]},
  "bride": {img:"👰", ex5:[{t:1,en:"The bride smiled.",kr:"신부가 미소 지었다."},{t:2,en:"The bride is radiant.",kr:"그 신부는 빛난다."},{t:3,en:"We greeted the bride.",kr:"우리는 신부를 맞이했다."},{t:4,en:"The groom gave the bride a ring.",kr:"신랑은 신부에게 반지를 주었다."},{t:5,en:"We found the bride lovely.",kr:"우리는 그 신부가 아름답다고 느꼈다."}]},
  "bridge": {img:"🌉", ex5:[{t:1,en:"The bridge stood.",kr:"다리가 서 있었다."},{t:2,en:"The bridge is long.",kr:"그 다리는 길다."},{t:3,en:"We crossed the bridge.",kr:"우리는 다리를 건넜다."},{t:4,en:"The city gave us a new bridge.",kr:"그 도시는 우리에게 새 다리를 놓아 주었다."},{t:5,en:"We found the bridge sturdy.",kr:"우리는 그 다리가 튼튼하다고 느꼈다."}]},
  "brief": {img:"📄", ex5:[{t:1,en:"The talk was brief.",kr:"그 이야기는 짧았다."},{t:2,en:"The note is brief.",kr:"그 메모는 간단하다."},{t:3,en:"We kept it brief.",kr:"우리는 그것을 짧게 했다."},{t:4,en:"The boss gave us a brief.",kr:"상사는 우리에게 간단한 지침을 주었다."},{t:5,en:"We found the visit brief.",kr:"우리는 그 방문이 짧다고 느꼈다."}]},
  "briefing": {img:"📋", ex5:[{t:1,en:"The briefing started.",kr:"브리핑이 시작되었다."},{t:2,en:"The briefing is short.",kr:"그 브리핑은 짧다."},{t:3,en:"We attended the briefing.",kr:"우리는 브리핑에 참석했다."},{t:4,en:"The chief gave us a briefing.",kr:"책임자는 우리에게 브리핑을 했다."},{t:5,en:"We found the briefing clear.",kr:"우리는 그 브리핑이 명확하다고 느꼈다."}]},
  "briefly": {img:"⏱️", ex5:[{t:1,en:"He spoke briefly.",kr:"그는 간략히 말했다."},{t:2,en:"The light flashed briefly.",kr:"그 빛이 잠깐 번쩍였다."},{t:3,en:"We paused briefly.",kr:"우리는 잠시 멈췄다."},{t:4,en:"It briefly gave us a rest.",kr:"그것은 잠시 우리에게 휴식을 주었다."},{t:5,en:"We found it explained briefly.",kr:"우리는 그것이 간략히 설명된 것을 알았다."}]},
  "brigade": {img:"🪖", ex5:[{t:1,en:"The brigade advanced at dawn.",kr:"그 여단은 새벽에 진격했다."},{t:2,en:"He commanded an infantry brigade.",kr:"그는 보병 여단을 지휘했다."},{t:3,en:"The fire brigade arrived within minutes.",kr:"소방대가 몇 분 안에 도착했다."},{t:4,en:"A whole brigade was sent to the border.",kr:"여단 전체가 국경으로 파견되었다."},{t:5,en:"The brigade held the line for days.",kr:"그 여단은 며칠 동안 전선을 지켰다."}]},
