  "brighten": {img:"💡", ex5:[{t:1,en:"Smiles brighten the room.",kr:"미소가 방을 환하게 한다."},{t:2,en:"The sky is brightening.",kr:"하늘이 밝아지고 있다."},{t:3,en:"We brighten the space.",kr:"우리는 공간을 밝게 한다."},{t:4,en:"The news gave us a brighten mood.",kr:"그 소식은 우리에게 밝아진 기분을 안겼다."},{t:5,en:"We brighten the wall fresh.",kr:"우리는 그 벽을 산뜻하게 밝힌다."}]},
  "brilliant": {img:"✨", ex5:[{t:1,en:"The idea is brilliant.",kr:"그 아이디어는 훌륭하다."},{t:2,en:"The light is brilliant.",kr:"그 빛은 눈부시다."},{t:3,en:"We saw a brilliant show.",kr:"우리는 멋진 공연을 보았다."},{t:4,en:"The plan gave us a brilliant result.",kr:"그 계획은 우리에게 훌륭한 결과를 안겼다."},{t:5,en:"We found the work brilliant.",kr:"우리는 그 작업이 훌륭하다고 느꼈다."}]},
  "brim": {img:"👒", ex5:[{t:1,en:"The cup is full to the brim.",kr:"컵이 가장자리까지 가득 찼다."},{t:2,en:"The hat brim is wide.",kr:"그 모자챙은 넓다."},{t:3,en:"We filled it to the brim.",kr:"우리는 그것을 가득 채웠다."},{t:4,en:"The hat gave us a brim of shade.",kr:"그 모자는 우리에게 그늘진 챙을 주었다."},{t:5,en:"We found the glass brim full.",kr:"우리는 그 잔이 넘칠 듯 가득함을 알았다."}]},
  "bring": {img:"🎁", ex5:[{t:1,en:"Guests bring gifts.",kr:"손님들이 선물을 가져온다."},{t:2,en:"The rain is bringing relief.",kr:"비가 안도를 가져오고 있다."},{t:3,en:"We bring snacks.",kr:"우리는 간식을 가져온다."},{t:4,en:"She brings me joy.",kr:"그녀는 나에게 기쁨을 안겨 준다."},{t:5,en:"We bring the tools ready.",kr:"우리는 도구를 준비해 가져온다."}]},
  "bringing": {img:"📦", ex5:[{t:1,en:"He keeps bringing food.",kr:"그는 계속 음식을 가져온다."},{t:2,en:"The act of bringing is kind.",kr:"가져다주는 일은 친절하다."},{t:3,en:"We are bringing chairs.",kr:"우리는 의자를 가져오고 있다."},{t:4,en:"The cart gave us a way of bringing it.",kr:"그 수레는 우리에게 그것을 가져올 방법을 주었다."},{t:5,en:"We found her bringing flowers.",kr:"우리는 그녀가 꽃을 가져오는 것을 보았다."}]},
  "brings": {img:"🎀", ex5:[{t:1,en:"Spring brings warmth.",kr:"봄은 온기를 가져온다."},{t:2,en:"The mail brings news.",kr:"우편이 소식을 가져온다."},{t:3,en:"She brings lunch daily.",kr:"그녀는 매일 점심을 가져온다."},{t:4,en:"The deal brings us profit.",kr:"그 거래는 우리에게 이익을 가져다준다."},{t:5,en:"We watched him bring gifts.",kr:"우리는 그가 선물을 가져오는 것을 보았다."}]},
  "brink": {img:"🧗", ex5:[{t:1,en:"We stood on the brink.",kr:"우리는 벼랑 끝에 섰다."},{t:2,en:"The firm is on the brink.",kr:"그 회사는 위기 직전이다."},{t:3,en:"We reached the brink.",kr:"우리는 벼랑 끝에 이르렀다."},{t:4,en:"The crisis gave us a brink moment.",kr:"그 위기는 우리에게 벼랑 끝 순간을 안겼다."},{t:5,en:"We found the deal on the brink.",kr:"우리는 그 거래가 결렬 직전임을 알았다."}]},
  "brisk": {img:"🚶", ex5:[{t:1,en:"The walk was brisk.",kr:"그 걸음은 경쾌했다."},{t:2,en:"The air is brisk.",kr:"그 공기는 상쾌하다."},{t:3,en:"We took a brisk walk.",kr:"우리는 빠른 산책을 했다."},{t:4,en:"The morning gave us a brisk start.",kr:"그 아침은 우리에게 활기찬 출발을 주었다."},{t:5,en:"We found business brisk.",kr:"우리는 장사가 활발하다고 느꼈다."}]},
  "brisket": {img:"🥩", ex5:[{t:1,en:"He smoked the brisket for twelve hours.",kr:"그는 양지머리를 열두 시간 동안 훈제했다."},{t:2,en:"The brisket was tender and full of flavor.",kr:"그 양지머리는 부드럽고 풍미가 가득했다."},{t:3,en:"She braised the brisket slowly in broth.",kr:"그녀는 양지머리를 육수에 천천히 뭉근히 끓였다."},{t:4,en:"A good brisket needs patience to cook.",kr:"좋은 양지머리를 요리하려면 인내가 필요하다."},{t:5,en:"They sliced the brisket against the grain.",kr:"그들은 양지머리를 결 반대로 썰었다."}]},
  "brittle": {img:"🍂", ex5:[{t:1,en:"The old paper was dry and brittle.",kr:"그 낡은 종이는 마르고 부서지기 쉬웠다."},{t:2,en:"Cold makes the plastic brittle.",kr:"추위는 그 플라스틱을 부서지기 쉽게 만든다."},{t:3,en:"The brittle branch snapped easily.",kr:"그 부러지기 쉬운 가지는 쉽게 똑 부러졌다."},{t:4,en:"Her voice sounded brittle with fear.",kr:"그녀의 목소리는 두려움으로 갈라지듯 들렸다."},{t:5,en:"The dry leaves were brittle underfoot.",kr:"마른 잎들이 발밑에서 바스락거렸다."}]},
  "broach": {img:"💬", ex5:[{t:1,en:"She finally broached the difficult topic.",kr:"그녀는 마침내 그 어려운 주제를 꺼냈다."},{t:2,en:"He was afraid to broach the subject.",kr:"그는 그 화제를 꺼내기를 두려워했다."},{t:3,en:"I will broach the matter at dinner.",kr:"나는 저녁 식사 때 그 문제를 꺼낼 것이다."},{t:4,en:"No one wanted to broach the issue.",kr:"아무도 그 문제를 꺼내고 싶어 하지 않았다."},{t:5,en:"She gently broached the idea of moving.",kr:"그녀는 이사 가는 생각을 조심스럽게 꺼냈다."}]},
  "broad": {img:"📏", ex5:[{t:1,en:"The road is broad.",kr:"그 길은 넓다."},{t:2,en:"His view is broad.",kr:"그의 시야는 넓다."},{t:3,en:"We took a broad view.",kr:"우리는 폭넓은 시각을 취했다."},{t:4,en:"The course gave us broad skills.",kr:"그 강좌는 우리에게 폭넓은 기술을 주었다."},{t:5,en:"We found the topic broad.",kr:"우리는 그 주제가 폭넓다고 느꼈다."}]},
  "broadcast": {img:"📡", ex5:[{t:1,en:"The broadcast aired.",kr:"방송이 송출되었다."},{t:2,en:"The broadcast is live.",kr:"그 방송은 생방송이다."},{t:3,en:"We watched the broadcast.",kr:"우리는 그 방송을 보았다."},{t:4,en:"The station gave us a broadcast.",kr:"그 방송국은 우리에게 방송을 송출해 주었다."},{t:5,en:"We found the broadcast clear.",kr:"우리는 그 방송이 선명하다고 느꼈다."}]},
  "broadcaster": {img:"📺", ex5:[{t:1,en:"The broadcaster announced the results live.",kr:"그 방송인이 결과를 생방송으로 알렸다."},{t:2,en:"A famous broadcaster hosted the show.",kr:"유명한 방송인이 그 프로그램을 진행했다."},{t:3,en:"The broadcaster reported from the scene.",kr:"그 방송인이 현장에서 보도했다."},{t:4,en:"The national broadcaster aired the speech.",kr:"국영 방송사가 그 연설을 방송했다."},{t:5,en:"The broadcaster interviewed the winning team.",kr:"그 방송인이 우승 팀을 인터뷰했다."}]},
