  "broke": {img:"💔", ex5:[{t:1,en:"The vase broke.",kr:"꽃병이 깨졌다."},{t:2,en:"The deal broke down.",kr:"그 거래가 결렬되었다."},{t:3,en:"We broke the record.",kr:"우리는 기록을 깼다."},{t:4,en:"The fall broke us a leg.",kr:"그 넘어짐은 우리에게 다리 골절을 안겼다."},{t:5,en:"We found the cup broke.",kr:"우리는 그 컵이 깨진 것을 알았다."}]},
  "broken": {img:"🧩", ex5:[{t:1,en:"The glass is broken.",kr:"유리가 깨졌다."},{t:2,en:"The phone is broken.",kr:"그 전화기는 고장 났다."},{t:3,en:"They broken the promise.",kr:"그들은 약속을 깼다."},{t:4,en:"The storm left us a broken fence.",kr:"그 폭풍은 우리에게 부서진 울타리를 남겼다."},{t:5,en:"We found the toy broken.",kr:"우리는 그 장난감이 망가진 것을 알았다."}]},
  "broker": {img:"💼", ex5:[{t:1,en:"The broker called.",kr:"중개인이 전화했다."},{t:2,en:"The broker is sharp.",kr:"그 중개인은 예리하다."},{t:3,en:"We hired a broker.",kr:"우리는 중개인을 고용했다."},{t:4,en:"The broker gave us advice.",kr:"그 중개인은 우리에게 조언을 했다."},{t:5,en:"We found the broker honest.",kr:"우리는 그 중개인이 정직하다고 느꼈다."}]},
  "brokerage": {img:"🏦", ex5:[{t:1,en:"She opened an account with a brokerage firm.",kr:"그녀는 증권 중개 회사에 계좌를 개설했다."},{t:2,en:"The brokerage charges a small commission.",kr:"그 중개업체는 소액의 수수료를 받는다."},{t:3,en:"He works at a large brokerage downtown.",kr:"그는 시내의 큰 중개 회사에서 일한다."},{t:4,en:"The brokerage handles stocks and bonds.",kr:"그 중개업체는 주식과 채권을 취급한다."},{t:5,en:"Online brokerage has lowered trading fees.",kr:"온라인 중개는 거래 수수료를 낮췄다."}]},
  "bronze": {img:"🥉", ex5:[{t:1,en:"The bronze gleamed.",kr:"청동이 빛났다."},{t:2,en:"The medal is bronze.",kr:"그 메달은 동메달이다."},{t:3,en:"We won bronze.",kr:"우리는 동메달을 땄다."},{t:4,en:"The games gave us a bronze medal.",kr:"그 대회는 우리에게 동메달을 안겼다."},{t:5,en:"We found the bronze statue old.",kr:"우리는 그 청동상이 오래됐다고 느꼈다."}]},
  "brooch": {img:"📌", ex5:[{t:1,en:"She pinned a brooch to her coat.",kr:"그녀는 외투에 브로치를 달았다."},{t:2,en:"The brooch was shaped like a flower.",kr:"그 브로치는 꽃 모양이었다."},{t:3,en:"An old brooch belonged to her grandmother.",kr:"오래된 브로치는 그녀의 할머니 것이었다."},{t:4,en:"The jeweled brooch sparkled.",kr:"보석 박힌 브로치가 반짝였다."},{t:5,en:"He gave her a silver brooch.",kr:"그는 그녀에게 은 브로치를 주었다."}]},
  "brook": {img:"🏞️", ex5:[{t:1,en:"The brook flowed.",kr:"시냇물이 흘렀다."},{t:2,en:"The brook is clear.",kr:"그 시내는 맑다."},{t:3,en:"We crossed the brook.",kr:"우리는 시내를 건넜다."},{t:4,en:"The forest gave us a brook.",kr:"그 숲은 우리에게 시냇물을 보여주었다."},{t:5,en:"We found the brook cold.",kr:"우리는 그 시내가 차갑다고 느꼈다."}]},
  "broom": {img:"🧹", ex5:[{t:1,en:"The broom swept.",kr:"빗자루가 쓸었다."},{t:2,en:"The broom is worn.",kr:"그 빗자루는 닳았다."},{t:3,en:"We used the broom.",kr:"우리는 빗자루를 썼다."},{t:4,en:"Mom gave me a broom.",kr:"엄마는 나에게 빗자루를 주셨다."},{t:5,en:"We found the broom handy.",kr:"우리는 그 빗자루가 편리하다고 느꼈다."}]},
  "broth": {img:"🍜", ex5:[{t:1,en:"The broth simmered.",kr:"육수가 끓었다."},{t:2,en:"The broth is rich.",kr:"그 육수는 진하다."},{t:3,en:"We made broth.",kr:"우리는 육수를 만들었다."},{t:4,en:"The cook gave us broth.",kr:"그 요리사는 우리에게 육수를 내주었다."},{t:5,en:"We found the broth tasty.",kr:"우리는 그 육수가 맛있다고 느꼈다."}]},
  "brother": {img:"👦", ex5:[{t:1,en:"My brother helped.",kr:"내 형이 도왔다."},{t:2,en:"My brother is tall.",kr:"우리 형은 키가 크다."},{t:3,en:"We call our brother.",kr:"우리는 형에게 전화한다."},{t:4,en:"My brother gave me a gift.",kr:"형은 나에게 선물을 주었다."},{t:5,en:"We found our brother kind.",kr:"우리는 형이 다정하다고 느꼈다."}]},
  "brothers": {img:"👬", ex5:[{t:1,en:"Brothers quarreled.",kr:"형제들이 다퉜다."},{t:2,en:"The brothers are close.",kr:"그 형제들은 사이가 좋다."},{t:3,en:"We met the brothers.",kr:"우리는 그 형제들을 만났다."},{t:4,en:"Dad gave the brothers bikes.",kr:"아빠는 형제들에게 자전거를 주셨다."},{t:5,en:"We found the brothers alike.",kr:"우리는 그 형제들이 닮았다고 느꼈다."}]},
  "brought": {img:"📥", ex5:[{t:1,en:"She brought cake.",kr:"그녀는 케이크를 가져왔다."},{t:2,en:"The wind brought rain.",kr:"바람이 비를 몰고 왔다."},{t:3,en:"They brought gifts.",kr:"그들은 선물을 가져왔다."},{t:4,en:"He brought us good news.",kr:"그는 우리에게 좋은 소식을 가져왔다."},{t:5,en:"We found the parcel brought early.",kr:"우리는 소포가 일찍 온 것을 알았다."}]},
  "brow": {img:"🤨", ex5:[{t:1,en:"His brow furrowed.",kr:"그의 이마가 찌푸려졌다."},{t:2,en:"The brow is wide.",kr:"그 이마는 넓다."},{t:3,en:"We wiped the brow.",kr:"우리는 이마를 닦았다."},{t:4,en:"The heat gave us a sweaty brow.",kr:"더위는 우리에게 땀 젖은 이마를 안겼다."},{t:5,en:"We found his brow raised.",kr:"우리는 그가 눈썹을 치켜올린 것을 보았다."}]},
