  "buoy": {img:"🛟", ex5:[{t:1,en:"A red buoy marked the channel.",kr:"빨간 부표가 항로를 표시했다."},{t:2,en:"The buoy bobbed on the waves.",kr:"그 부표가 물결 위에서 까닥거렸다."},{t:3,en:"Sailors steered past the buoy.",kr:"선원들은 부표를 지나 조종했다."},{t:4,en:"Good news helped buoy his spirits.",kr:"좋은 소식이 그의 기운을 북돋웠다."},{t:5,en:"The buoy warned of shallow water.",kr:"그 부표가 얕은 물을 경고했다."}]},
  "buoyancy": {img:"🎈", ex5:[{t:1,en:"The raft's buoyancy kept them afloat.",kr:"뗏목의 부력이 그들을 띄웠다."},{t:2,en:"Her buoyancy lifted the whole team.",kr:"그녀의 쾌활함이 팀 전체를 띄웠다."},{t:3,en:"The market showed new buoyancy.",kr:"시장은 새로운 활기를 보였다."},{t:4,en:"Salt water adds to buoyancy.",kr:"소금물은 부력을 더한다."},{t:5,en:"His mood kept its buoyancy.",kr:"그의 기분은 활기를 유지했다."}]},
  "buoyant": {img:"🎈", ex5:[{t:1,en:"The cork is light and buoyant.",kr:"그 코르크는 가볍고 잘 뜬다."},{t:2,en:"She was in a buoyant mood.",kr:"그녀는 들뜬 기분이었다."},{t:3,en:"The buoyant raft floated easily.",kr:"그 잘 뜨는 뗏목이 쉽게 떠다녔다."},{t:4,en:"His buoyant spirit cheered the team.",kr:"그의 쾌활한 기운이 팀을 북돋웠다."},{t:5,en:"Salt water is more buoyant than fresh.",kr:"소금물은 민물보다 부력이 크다."}]},
