  "calico": {img:"🐈", ex5:[{t:1,en:"The calico cat had orange and black patches.",kr:"그 삼색 고양이는 주황과 검정 무늬가 있었다."},{t:2,en:"She sewed a dress from calico cloth.",kr:"그녀는 옥양목 천으로 원피스를 지었다."},{t:3,en:"The calico fabric had a small floral print.",kr:"그 옥양목 천에는 작은 꽃무늬가 있었다."},{t:4,en:"A calico curtain hung in the window.",kr:"옥양목 커튼이 창문에 걸려 있었다."},{t:5,en:"Their calico kitten napped in the sun.",kr:"그들의 삼색 새끼 고양이가 햇볕에서 낮잠을 잤다."}]},
  "caliper": {img:"📏", ex5:[{t:1,en:"He measured the thickness with a caliper.",kr:"그는 캘리퍼로 두께를 측정했다."},{t:2,en:"A digital caliper gives precise readings.",kr:"디지털 캘리퍼는 정밀한 수치를 제공한다."},{t:3,en:"The mechanic checked the brake caliper.",kr:"정비공은 브레이크 캘리퍼를 점검했다."},{t:4,en:"She used a caliper to gauge the bolt's diameter.",kr:"그녀는 볼트의 지름을 재기 위해 캘리퍼를 사용했다."},{t:5,en:"A worn caliper can cause uneven braking.",kr:"마모된 캘리퍼는 고르지 않은 제동을 일으킬 수 있다."}]},
  "calisthenics": {img:"💪", ex5:[{t:1,en:"The soldiers did calisthenics at dawn.",kr:"병사들은 새벽에 맨몸 체조를 했다."},{t:2,en:"Calisthenics build strength without weights.",kr:"맨몸 운동은 기구 없이 힘을 기른다."},{t:3,en:"He prefers calisthenics to the gym.",kr:"그는 헬스장보다 맨몸 운동을 선호한다."},{t:4,en:"A simple calisthenics routine takes ten minutes.",kr:"간단한 맨몸 체조 루틴은 십 분이면 된다."},{t:5,en:"Calisthenics can be done anywhere.",kr:"맨몸 운동은 어디서든 할 수 있다."}]},
  "call": {img:"📞", ex5:[{t:1,en:"Phones call.",kr:"전화가 울린다."},{t:2,en:"The bird is calling.",kr:"새가 울고 있다."},{t:3,en:"We call a friend.",kr:"우리는 친구에게 전화한다."},{t:4,en:"She gave us a call.",kr:"그녀는 우리에게 전화를 주었다."},{t:5,en:"We call the dog Max.",kr:"우리는 그 개를 맥스라고 부른다."}]},
  "called": {img:"☎️", ex5:[{t:1,en:"He called twice.",kr:"그는 두 번 전화했다."},{t:2,en:"The dog is called Rex.",kr:"그 개는 렉스라고 불린다."},{t:3,en:"They called a meeting.",kr:"그들은 회의를 소집했다."},{t:4,en:"She called us a cab.",kr:"그녀는 우리에게 택시를 불러 주었다."},{t:5,en:"We called the plan bold.",kr:"우리는 그 계획을 대담하다고 평했다."}]},
  "caller": {img:"📱", ex5:[{t:1,en:"The caller waited.",kr:"전화 건 사람이 기다렸다."},{t:2,en:"The caller is polite.",kr:"그 발신자는 정중하다."},{t:3,en:"We greeted the caller.",kr:"우리는 발신자를 맞이했다."},{t:4,en:"The caller gave us a tip.",kr:"그 발신자는 우리에게 제보를 주었다."},{t:5,en:"We found the caller anonymous.",kr:"우리는 그 발신자가 익명임을 알았다."}]},
  "calligraphy": {img:"🖌️", ex5:[{t:1,en:"She studied Chinese calligraphy for years.",kr:"그녀는 여러 해 동안 중국 서예를 공부했다."},{t:2,en:"The invitation featured elegant calligraphy.",kr:"그 초대장은 우아한 캘리그래피로 꾸며졌다."},{t:3,en:"He practiced calligraphy with a brush and ink.",kr:"그는 붓과 먹으로 서예를 연습했다."},{t:4,en:"Beautiful calligraphy takes patience to master.",kr:"아름다운 서예를 익히려면 인내가 필요하다."},{t:5,en:"The museum displayed ancient calligraphy.",kr:"그 박물관은 고대 서예를 전시했다."}]},
  "calling": {img:"📲", ex5:[{t:1,en:"Someone is calling.",kr:"누군가 전화하고 있다."},{t:2,en:"Teaching is her calling.",kr:"가르침은 그녀의 천직이다."},{t:3,en:"We are calling the office.",kr:"우리는 사무실에 전화하고 있다."},{t:4,en:"The job gave us a calling.",kr:"그 일은 우리에게 천직을 안겼다."},{t:5,en:"We found him calling for help.",kr:"우리는 그가 도움을 청하는 것을 알았다."}]},
  "callous": {img:"😑", ex5:[{t:1,en:"His callous reply hurt her.",kr:"그의 냉담한 답이 그녀를 아프게 했다."},{t:2,en:"It was callous to ignore their pain.",kr:"그들의 고통을 무시하는 것은 냉담한 일이었다."},{t:3,en:"She was shocked by his callous manner.",kr:"그녀는 그의 냉담한 태도에 충격받았다."},{t:4,en:"A callous remark can wound deeply.",kr:"냉담한 말 한마디가 깊은 상처를 줄 수 있다."},{t:5,en:"He grew callous after years of hardship.",kr:"그는 오랜 고난 끝에 냉담해졌다."}]},
  "callously": {img:"🧊", ex5:[{t:1,en:"He callously ignored their suffering.",kr:"그는 그들의 고통을 냉담하게 무시했다."},{t:2,en:"She spoke callously about the loss.",kr:"그녀는 그 상실에 대해 무정하게 말했다."},{t:3,en:"They callously abandoned the project.",kr:"그들은 그 프로젝트를 매정하게 내팽개쳤다."},{t:4,en:"He treated the workers callously.",kr:"그는 일꾼들을 냉정하게 대했다."},{t:5,en:"The decision was made callously.",kr:"그 결정은 무정하게 내려졌다."}]},
  "callousness": {img:"🧊", ex5:[{t:1,en:"His callousness shocked his colleagues.",kr:"그의 냉담함이 동료들을 충격에 빠뜨렸다."},{t:2,en:"The report exposed the company's callousness.",kr:"그 보고서는 회사의 무정함을 폭로했다."},{t:3,en:"She was hurt by his callousness.",kr:"그녀는 그의 무정함에 상처받았다."},{t:4,en:"Their callousness toward the poor angered many.",kr:"가난한 이들에 대한 그들의 냉담함이 많은 이를 분노케 했다."},{t:5,en:"His callousness grew over the years.",kr:"그의 무정함은 세월이 흐르며 커졌다."}]},
  "callow": {img:"🐣", ex5:[{t:1,en:"He was a callow youth fresh from school.",kr:"그는 학교를 갓 나온 풋내기 젊은이였다."},{t:2,en:"Her callow remarks revealed her age.",kr:"그녀의 미숙한 말들이 나이를 드러냈다."},{t:3,en:"The callow recruit needed much training.",kr:"그 풋내기 신참은 많은 훈련이 필요했다."},{t:4,en:"He outgrew his callow, reckless days.",kr:"그는 미숙하고 무모하던 시절을 벗어났다."},{t:5,en:"A callow writer often imitates others.",kr:"미숙한 작가는 흔히 남을 흉내 낸다."}]},
  "calls": {img:"📞", ex5:[{t:1,en:"Calls poured in.",kr:"전화가 쇄도했다."},{t:2,en:"The calls are urgent.",kr:"그 전화들은 긴급하다."},{t:3,en:"We took the calls.",kr:"우리는 전화를 받았다."},{t:4,en:"The line gave us many calls.",kr:"그 회선은 우리에게 많은 전화를 안겼다."},{t:5,en:"We found the calls helpful.",kr:"우리는 그 전화들이 도움이 된다고 느꼈다."}]},
