  "calmly": {img:"🧘", ex5:[{t:1,en:"She spoke calmly.",kr:"그녀는 차분히 말했다."},{t:2,en:"He waited calmly.",kr:"그는 침착하게 기다렸다."},{t:3,en:"We acted calmly.",kr:"우리는 침착하게 행동했다."},{t:4,en:"It calmly gave us reassurance.",kr:"그것은 우리에게 차분히 안도를 주었다."},{t:5,en:"We found him reacting calmly.",kr:"우리는 그가 침착하게 반응함을 알았다."}]},
  "calorie": {img:"🔥", ex5:[{t:1,en:"A calorie counts.",kr:"한 칼로리도 중요하다."},{t:2,en:"The calorie count is high.",kr:"그 칼로리 수치는 높다."},{t:3,en:"We track each calorie.",kr:"우리는 칼로리 하나하나를 기록한다."},{t:4,en:"The label gave us a calorie figure.",kr:"그 라벨은 우리에게 칼로리 수치를 알려주었다."},{t:5,en:"We found the calorie info clear.",kr:"우리는 그 칼로리 정보가 명확하다고 느꼈다."}]},
  "calories": {img:"🍩", ex5:[{t:1,en:"Calories add up.",kr:"칼로리가 쌓인다."},{t:2,en:"The calories are listed.",kr:"그 칼로리가 표시되어 있다."},{t:3,en:"We counted the calories.",kr:"우리는 칼로리를 셌다."},{t:4,en:"The menu gave us calories per dish.",kr:"그 메뉴는 우리에게 음식별 칼로리를 알려주었다."},{t:5,en:"We found the calories high.",kr:"우리는 그 칼로리가 높다고 느꼈다."}]},
  "calumny": {img:"🗯️", ex5:[{t:1,en:"He sued the paper for calumny.",kr:"그는 그 신문을 중상모략으로 고소했다."},{t:2,en:"The calumny spread faster than the truth.",kr:"그 비방은 진실보다 빠르게 퍼졌다."},{t:3,en:"She faced years of cruel calumny.",kr:"그녀는 수년간의 잔인한 중상을 겪었다."},{t:4,en:"Calumny can ruin an honest name.",kr:"중상모략은 정직한 명예를 망칠 수 있다."},{t:5,en:"He answered the calumny with calm proof.",kr:"그는 차분한 증거로 그 비방에 대응했다."}]},
  "camaraderie": {img:"🤝", ex5:[{t:1,en:"The team's camaraderie grew stronger after the long trip.",kr:"긴 여정 끝에 팀의 동료애가 더욱 깊어졌다."},{t:2,en:"There was a warm camaraderie among the old soldiers.",kr:"노병들 사이에는 따뜻한 전우애가 있었다."},{t:3,en:"Shared hardship built a lasting camaraderie between them.",kr:"함께한 고난이 그들 사이에 지속적인 유대감을 쌓았다."},{t:4,en:"He missed the camaraderie of his college days.",kr:"그는 대학 시절의 우정 어린 동료애를 그리워했다."},{t:5,en:"The kitchen staff worked with easy camaraderie all night.",kr:"주방 직원들은 밤새 편안한 동료애 속에서 일했다."}]},
  "camel": {img:"🐪", ex5:[{t:1,en:"The camel walked.",kr:"낙타가 걸었다."},{t:2,en:"The camel is tall.",kr:"그 낙타는 키가 크다."},{t:3,en:"We rode a camel.",kr:"우리는 낙타를 탔다."},{t:4,en:"The desert gave us a camel ride.",kr:"그 사막은 우리에게 낙타 타기를 선사했다."},{t:5,en:"We found the camel gentle.",kr:"우리는 그 낙타가 온순하다고 느꼈다."}]},
  "camellia": {img:"🌺", ex5:[{t:1,en:"A white camellia bloomed in the winter garden.",kr:"흰 동백꽃이 겨울 정원에서 피었다."},{t:2,en:"The camellia has glossy, dark green leaves.",kr:"동백나무는 윤기 나는 짙은 초록 잎을 지녔다."},{t:3,en:"She wore a camellia in her hair.",kr:"그녀는 머리에 동백꽃을 꽂았다."},{t:4,en:"The camellia flowers when little else does.",kr:"동백은 다른 꽃이 거의 피지 않을 때 핀다."},{t:5,en:"A pink camellia adorned the entrance.",kr:"분홍 동백꽃이 입구를 장식했다."}]},
  "camera": {img:"📷", ex5:[{t:1,en:"The camera clicked.",kr:"카메라가 찰칵했다."},{t:2,en:"The camera is new.",kr:"그 카메라는 새것이다."},{t:3,en:"We used the camera.",kr:"우리는 카메라를 썼다."},{t:4,en:"Dad gave me a camera.",kr:"아빠는 나에게 카메라를 주셨다."},{t:5,en:"We found the camera blurry.",kr:"우리는 그 카메라가 흐릿하게 찍힌다고 느꼈다."}]},
