  "capitalism": {img:"💵", ex5:[{t:1,en:"Capitalism rewards competition and risk.",kr:"자본주의는 경쟁과 위험 감수에 보상한다."},{t:2,en:"They debated the merits of capitalism.",kr:"그들은 자본주의의 장점을 두고 토론했다."},{t:3,en:"Capitalism drives much of the global economy.",kr:"자본주의는 세계 경제의 많은 부분을 이끈다."},{t:4,en:"Critics blame capitalism for inequality.",kr:"비판자들은 불평등의 책임을 자본주의에 돌린다."},{t:5,en:"Capitalism encourages innovation and growth.",kr:"자본주의는 혁신과 성장을 장려한다."}]},
  "capitol": {img:"🏛️", ex5:[{t:1,en:"The capitol stood tall.",kr:"의사당이 우뚝 섰다."},{t:2,en:"The capitol is grand.",kr:"그 의사당은 웅장하다."},{t:3,en:"We toured the capitol.",kr:"우리는 의사당을 둘러보았다."},{t:4,en:"The guide gave us a capitol tour.",kr:"그 안내자는 우리에게 의사당 견학을 시켜 주었다."},{t:5,en:"We found the capitol majestic.",kr:"우리는 그 의사당이 장엄하다고 느꼈다."}]},
  "capitulate": {img:"🏳️", ex5:[{t:1,en:"The town had to capitulate at last.",kr:"그 도시는 마침내 항복해야 했다."},{t:2,en:"He refused to capitulate to threats.",kr:"그는 협박에 굴복하기를 거부했다."},{t:3,en:"They capitulated after long talks.",kr:"그들은 긴 협상 끝에 굴복했다."},{t:4,en:"The firm chose not to capitulate.",kr:"그 회사는 굴복하지 않기로 했다."},{t:5,en:"She would never capitulate so soon.",kr:"그녀는 그렇게 빨리 항복할 사람이 아니었다."}]},
  "capitulation": {img:"🏳️", ex5:[{t:1,en:"The general signed the capitulation.",kr:"그 장군은 항복 문서에 서명했다."},{t:2,en:"Their capitulation ended the long siege.",kr:"그들의 항복은 그 긴 포위를 끝냈다."},{t:3,en:"The deal felt like a total capitulation.",kr:"그 합의는 완전한 굴복처럼 느껴졌다."},{t:4,en:"Critics called the treaty a capitulation.",kr:"비평가들은 그 조약을 굴복이라 불렀다."},{t:5,en:"After months, capitulation seemed certain.",kr:"몇 달 후 항복은 확실해 보였다."}]},
  "caprice": {img:"🎲", ex5:[{t:1,en:"His sudden caprice changed all our plans.",kr:"그의 갑작스러운 변덕이 우리 계획을 모두 바꿔 놓았다."},{t:2,en:"The weather shifted at the caprice of the wind.",kr:"날씨가 바람의 변덕에 따라 바뀌었다."},{t:3,en:"She acted on a passing caprice.",kr:"그녀는 스쳐 가는 변덕에 따라 행동했다."},{t:4,en:"The king's caprice ruined the festival.",kr:"왕의 변덕이 그 축제를 망쳤다."},{t:5,en:"Fashion often follows the caprice of the crowd.",kr:"유행은 흔히 대중의 변덕을 따른다."}]},
  "capricious": {img:"🎲", ex5:[{t:1,en:"The weather here is famously capricious.",kr:"이곳 날씨는 변덕스럽기로 유명하다."},{t:2,en:"Her capricious moods kept them guessing.",kr:"그녀의 변덕스러운 기분에 그들은 늘 눈치를 봤다."},{t:3,en:"A capricious boss is hard to please.",kr:"변덕스러운 상사는 비위 맞추기가 어렵다."},{t:4,en:"The market can be capricious and sudden.",kr:"시장은 변덕스럽고 급변할 수 있다."},{t:5,en:"He made a capricious change of plans.",kr:"그는 변덕스럽게 계획을 바꿨다."}]},
