  "champion": {img:"🏆", ex5:[{t:1,en:"The champion won.",kr:"챔피언이 이겼다."},{t:2,en:"The champion is humble.",kr:"그 챔피언은 겸손하다."},{t:3,en:"We cheered the champion.",kr:"우리는 챔피언을 응원했다."},{t:4,en:"The title gave us a champion.",kr:"그 우승은 우리에게 챔피언을 안겼다."},{t:5,en:"We found the champion gracious.",kr:"우리는 그 챔피언이 너그럽다고 느꼈다."}]},
  "championship": {img:"🥇", ex5:[{t:1,en:"The championship ended.",kr:"선수권 대회가 끝났다."},{t:2,en:"The championship is fierce.",kr:"그 선수권은 치열하다."},{t:3,en:"We won the championship.",kr:"우리는 선수권을 차지했다."},{t:4,en:"The win gave us a championship.",kr:"그 승리는 우리에게 우승을 안겼다."},{t:5,en:"We found the championship thrilling.",kr:"우리는 그 선수권이 짜릿하다고 느꼈다."}]},
  "chance": {img:"🎲", ex5:[{t:1,en:"A chance came.",kr:"기회가 왔다."},{t:2,en:"The chance is slim.",kr:"그 가능성은 희박하다."},{t:3,en:"We took the chance.",kr:"우리는 그 기회를 잡았다."},{t:4,en:"The job gave us a chance.",kr:"그 일은 우리에게 기회를 주었다."},{t:5,en:"We found the chance rare.",kr:"우리는 그 기회가 드물다고 느꼈다."}]},
