  "change": {img:"🔄", ex5:[{t:1,en:"Seasons change.",kr:"계절이 바뀐다."},{t:2,en:"The plan is changing.",kr:"그 계획이 바뀌고 있다."},{t:3,en:"We change the rule.",kr:"우리는 그 규칙을 바꾼다."},{t:4,en:"The store gave us change.",kr:"그 가게는 우리에게 거스름돈을 주었다."},{t:5,en:"We change the plan quick.",kr:"우리는 그 계획을 재빨리 바꾼다."}]},
  "changed": {img:"♻️", ex5:[{t:1,en:"The world changed.",kr:"세상이 변했다."},{t:2,en:"The rule is changed.",kr:"그 규칙은 바뀌었다."},{t:3,en:"They changed the plan.",kr:"그들은 계획을 바꿨다."},{t:4,en:"The news changed us our minds.",kr:"그 소식은 우리 마음을 바꾸게 했다."},{t:5,en:"We found the schedule changed.",kr:"우리는 일정이 바뀐 것을 알았다."}]},
  "changes": {img:"🔀", ex5:[{t:1,en:"Changes happen.",kr:"변화가 일어난다."},{t:2,en:"The changes are big.",kr:"그 변화들은 크다."},{t:3,en:"We made changes.",kr:"우리는 변경을 했다."},{t:4,en:"The update gave us changes.",kr:"그 업데이트는 우리에게 변경 사항을 안겼다."},{t:5,en:"We found the changes helpful.",kr:"우리는 그 변화들이 도움이 된다고 느꼈다."}]},
  "changing": {img:"🌗", ex5:[{t:1,en:"The weather is changing.",kr:"날씨가 바뀌고 있다."},{t:2,en:"The act of changing is hard.",kr:"바꾸는 일은 어렵다."},{t:3,en:"We are changing tactics.",kr:"우리는 전술을 바꾸고 있다."},{t:4,en:"The trend gave us a changing market.",kr:"그 추세는 우리에게 변화하는 시장을 안겼다."},{t:5,en:"We found the rules changing.",kr:"우리는 규칙이 바뀌고 있음을 알았다."}]},
  "channel": {img:"📺", ex5:[{t:1,en:"The channel switched.",kr:"채널이 바뀌었다."},{t:2,en:"The channel is popular.",kr:"그 채널은 인기 있다."},{t:3,en:"We changed the channel.",kr:"우리는 채널을 바꿨다."},{t:4,en:"The cable gave us a new channel.",kr:"그 케이블은 우리에게 새 채널을 제공했다."},{t:5,en:"We found the channel clear.",kr:"우리는 그 채널이 선명하다고 느꼈다."}]},
  "chaos": {img:"🌀", ex5:[{t:1,en:"Chaos erupted.",kr:"혼돈이 터졌다."},{t:2,en:"The chaos is total.",kr:"그 혼란은 극심하다."},{t:3,en:"We escaped the chaos.",kr:"우리는 그 혼돈에서 벗어났다."},{t:4,en:"The storm gave us chaos.",kr:"그 폭풍은 우리에게 혼란을 안겼다."},{t:5,en:"We found the scene chaos.",kr:"우리는 그 현장이 아수라장임을 알았다."}]},
  "chapel": {img:"⛪", ex5:[{t:1,en:"They married in a small chapel.",kr:"그들은 작은 예배당에서 결혼했다."},{t:2,en:"The chapel had lovely stained glass.",kr:"그 예배당에는 아름다운 스테인드글라스가 있었다."},{t:3,en:"She prayed quietly in the chapel.",kr:"그녀는 예배당에서 조용히 기도했다."},{t:4,en:"The old chapel stood by the school.",kr:"그 오래된 예배당이 학교 옆에 서 있었다."},{t:5,en:"Bells rang from the chapel tower.",kr:"예배당 탑에서 종이 울렸다."}]},
