  "chop": {img:"🔪", ex5:[{t:1,en:"Cooks chop herbs.",kr:"요리사들이 허브를 다진다."},{t:2,en:"The wood is chopping easily.",kr:"그 나무가 잘 쪼개진다."},{t:3,en:"We chop the onions.",kr:"우리는 양파를 썬다."},{t:4,en:"The knife gave us a way to chop it.",kr:"그 칼은 우리에게 그것을 썰 방법을 주었다."},{t:5,en:"We chop the wood fine.",kr:"우리는 그 나무를 잘게 팬다."}]},
  "chord": {img:"🎸", ex5:[{t:1,en:"The chord rang.",kr:"화음이 울렸다."},{t:2,en:"The chord is minor.",kr:"그 코드는 단조이다."},{t:3,en:"We played a chord.",kr:"우리는 화음을 연주했다."},{t:4,en:"The song gave us a sad chord.",kr:"그 노래는 우리에게 애절한 화음을 들려주었다."},{t:5,en:"We found the chord soothing.",kr:"우리는 그 화음이 마음을 달랜다고 느꼈다."}]},
