  "contagion": {img:"🦠", ex5:[{t:1,en:"They feared the spread of contagion.",kr:"그들은 전염병의 확산을 두려워했다."},{t:2,en:"Strict steps slowed the contagion.",kr:"엄격한 조치가 전염을 늦췄다."},{t:3,en:"Panic spread like a contagion.",kr:"공포가 전염병처럼 번졌다."},{t:4,en:"The contagion reached the next town.",kr:"그 전염병이 옆 마을에 닿았다."},{t:5,en:"Clean hands limit contagion.",kr:"손을 깨끗이 하면 전염이 줄어든다."}]},
  "contagious": {img:"🦠", ex5:[{t:1,en:"The flu is highly contagious.",kr:"독감은 전염성이 매우 강하다."},{t:2,en:"Her laughter was wonderfully contagious.",kr:"그녀의 웃음은 놀랍도록 전염성이 있었다."},{t:3,en:"The disease is contagious in its early stage.",kr:"그 병은 초기 단계에 전염성이 있다."},{t:4,en:"His enthusiasm proved contagious.",kr:"그의 열정은 전염성이 있는 것으로 드러났다."},{t:5,en:"They isolated the contagious patients.",kr:"그들은 전염성 있는 환자들을 격리했다."}]},
  "contain": {img:"📦", ex5:[{t:1,en:"Boxes contain goods.",kr:"상자는 물건을 담는다."},{t:2,en:"The jar is containing jam.",kr:"그 병에 잼이 담겨 있다."},{t:3,en:"We contain the spill.",kr:"우리는 그 유출을 막는다."},{t:4,en:"The bottle gave us a way to contain it.",kr:"그 병은 우리에게 그것을 담을 방법을 주었다."},{t:5,en:"We contain the fire fast.",kr:"우리는 그 불을 빠르게 진압한다."}]},
  "contained": {img:"🫙", ex5:[{t:1,en:"The leak was contained.",kr:"누출이 차단되었다."},{t:2,en:"The fire is contained.",kr:"그 불은 진압되었다."},{t:3,en:"They contained the outbreak.",kr:"그들은 그 발병을 억제했다."},{t:4,en:"The box contained us a surprise.",kr:"그 상자는 우리에게 깜짝 선물을 담고 있었다."},{t:5,en:"We found the spill contained.",kr:"우리는 그 유출이 차단된 것을 알았다."}]},
  "container": {img:"🚢", ex5:[{t:1,en:"The container shipped.",kr:"컨테이너가 운송되었다."},{t:2,en:"The container is sealed.",kr:"그 용기는 밀봉되어 있다."},{t:3,en:"We filled the container.",kr:"우리는 용기를 채웠다."},{t:4,en:"The store gave us a container.",kr:"그 가게는 우리에게 용기를 주었다."},{t:5,en:"We found the container leaking.",kr:"우리는 그 용기가 새는 것을 알았다."}]},
  "contaminate": {img:"☣️", ex5:[{t:1,en:"Waste can contaminate the water.",kr:"폐기물은 물을 오염시킬 수 있다."},{t:2,en:"They feared the soil was contaminated.",kr:"그들은 흙이 오염되었을까 봐 걱정했다."},{t:3,en:"Dirty hands can contaminate food.",kr:"더러운 손은 음식을 오염시킬 수 있다."},{t:4,en:"The spill contaminated the river.",kr:"그 유출이 강을 오염시켰다."},{t:5,en:"Keep the sample from being contaminated.",kr:"표본이 오염되지 않게 해라."}]},
  "contamination": {img:"☣️", ex5:[{t:1,en:"The contamination of the water alarmed officials.",kr:"물의 오염이 당국을 놀라게 했다."},{t:2,en:"They tested the soil for contamination.",kr:"그들은 토양의 오염 여부를 검사했다."},{t:3,en:"Cross contamination can spoil food.",kr:"교차 오염은 음식을 상하게 할 수 있다."},{t:4,en:"The contamination spread through the supply.",kr:"그 오염이 공급망 전체로 퍼졌다."},{t:5,en:"Strict cleaning prevents contamination.",kr:"철저한 청소가 오염을 막는다."}]},
  "contemplate": {img:"🤔", ex5:[{t:1,en:"She sat quietly to contemplate the view.",kr:"그녀는 그 경치를 음미하려고 조용히 앉았다."},{t:2,en:"He contemplated changing his job.",kr:"그는 직업을 바꾸는 것을 곰곰이 생각했다."},{t:3,en:"They contemplated the meaning of the story.",kr:"그들은 그 이야기의 의미를 곰곰이 생각했다."},{t:4,en:"She paused to contemplate her next step.",kr:"그녀는 다음 단계를 생각하려고 잠시 멈췄다."},{t:5,en:"He likes to contemplate by the sea.",kr:"그는 바닷가에서 사색하기를 좋아한다."}]},
  "contemplation": {img:"🧘", ex5:[{t:1,en:"He sat in quiet contemplation by the lake.",kr:"그는 호숫가에서 조용한 사색에 잠겨 앉아 있었다."},{t:2,en:"The decision took weeks of contemplation.",kr:"그 결정에는 몇 주의 숙고가 필요했다."},{t:3,en:"Her face wore a look of deep contemplation.",kr:"그녀의 얼굴에 깊은 사색의 표정이 어렸다."},{t:4,en:"The garden invited peaceful contemplation.",kr:"그 정원은 평온한 사색을 불러왔다."},{t:5,en:"After much contemplation, he agreed.",kr:"많은 숙고 끝에 그가 동의했다."}]},
  "contemporary": {img:"🖼️", ex5:[{t:1,en:"The art is contemporary.",kr:"그 예술은 현대적이다."},{t:2,en:"The style is contemporary.",kr:"그 양식은 현대적이다."},{t:3,en:"We toured contemporary art.",kr:"우리는 현대 미술을 둘러보았다."},{t:4,en:"The show gave us contemporary works.",kr:"그 전시는 우리에게 현대 작품을 선보였다."},{t:5,en:"We found the design contemporary.",kr:"우리는 그 디자인이 현대적이라고 느꼈다."}]},
  "contempt": {img:"😒", ex5:[{t:1,en:"Contempt showed.",kr:"경멸이 드러났다."},{t:2,en:"His contempt is clear.",kr:"그의 경멸은 분명하다."},{t:3,en:"We felt contempt.",kr:"우리는 경멸을 느꼈다."},{t:4,en:"The sneer gave us a sense of contempt.",kr:"그 비웃음은 우리에게 경멸감을 안겼다."},{t:5,en:"We found the contempt obvious.",kr:"우리는 그 경멸이 뚜렷하다고 느꼈다."}]},
  "contend": {img:"🥊", ex5:[{t:1,en:"Teams contend for the cup.",kr:"팀들이 우승컵을 다툰다."},{t:2,en:"The rivals are contending hard.",kr:"그 경쟁자들이 치열하게 겨루고 있다."},{t:3,en:"We contend for the title.",kr:"우리는 우승을 다툰다."},{t:4,en:"The race gave us a chance to contend.",kr:"그 경주는 우리에게 겨룰 기회를 주었다."},{t:5,en:"We contend the call wrong.",kr:"우리는 그 판정이 틀렸다고 주장한다."}]},
  "contender": {img:"🏆", ex5:[{t:1,en:"She is a serious contender for the prize.",kr:"그녀는 그 상의 유력한 경쟁자다."},{t:2,en:"The contender trained for the championship.",kr:"그 경쟁자는 챔피언십을 위해 훈련했다."},{t:3,en:"Several contenders entered the race.",kr:"여러 경쟁자가 그 경주에 참가했다."},{t:4,en:"He emerged as the leading contender.",kr:"그는 선두 경쟁자로 떠올랐다."},{t:5,en:"The young contender surprised everyone.",kr:"그 젊은 경쟁자가 모두를 놀라게 했다."}]},
