  "cornerstone": {img:"🧱", ex5:[{t:1,en:"Trust is the cornerstone of teamwork.",kr:"신뢰는 협업의 초석이다."},{t:2,en:"They laid the building's cornerstone.",kr:"그들은 건물의 주춧돌을 놓았다."},{t:3,en:"Honesty was the cornerstone of his life.",kr:"정직은 그의 삶의 초석이었다."},{t:4,en:"Education is a cornerstone of progress.",kr:"교육은 발전의 초석이다."},{t:5,en:"The deal is the cornerstone of growth.",kr:"그 거래는 성장의 토대다."}]},
  "cornice": {img:"🏛️", ex5:[{t:1,en:"An ornate cornice topped the building.",kr:"화려한 처마 돌림띠가 건물 꼭대기를 장식했다."},{t:2,en:"Dust gathered along the old cornice.",kr:"먼지가 낡은 코니스를 따라 쌓였다."},{t:3,en:"The cornice cast a shadow on the wall.",kr:"그 처마 장식이 벽에 그림자를 드리웠다."},{t:4,en:"Workers restored the carved cornice.",kr:"인부들은 조각된 코니스를 복원했다."},{t:5,en:"A plaster cornice ran around the ceiling.",kr:"석고 돌림띠가 천장을 빙 둘렀다."}]},
  "corollary": {img:"➡️", ex5:[{t:1,en:"Stress is a corollary of overwork.",kr:"스트레스는 과로의 필연적 결과다."},{t:2,en:"The theory has a clear corollary.",kr:"그 이론에는 분명한 따름정리가 있다."},{t:3,en:"Higher pay was a corollary of growth.",kr:"임금 인상은 성장의 부수적 결과였다."},{t:4,en:"As a corollary, costs also rose.",kr:"그 결과로 비용도 올랐다."},{t:5,en:"Trust is a corollary of honesty.",kr:"신뢰는 정직의 자연스러운 귀결이다."}]},
  "corporate": {img:"🏢", ex5:[{t:1,en:"Corporate profits rose.",kr:"기업 이익이 올랐다."},{t:2,en:"The culture is corporate.",kr:"그 문화는 기업적이다."},{t:3,en:"We joined the corporate team.",kr:"우리는 그 기업 팀에 합류했다."},{t:4,en:"The firm gave us corporate perks.",kr:"그 회사는 우리에게 기업 복지를 주었다."},{t:5,en:"We found the corporate style strict.",kr:"우리는 그 기업 방식이 엄격하다고 느꼈다."}]},
  "corporation": {img:"🏬", ex5:[{t:1,en:"The corporation grew.",kr:"기업이 성장했다."},{t:2,en:"The corporation is huge.",kr:"그 기업은 거대하다."},{t:3,en:"We sued the corporation.",kr:"우리는 그 기업을 고소했다."},{t:4,en:"The corporation gave us jobs.",kr:"그 기업은 우리에게 일자리를 주었다."},{t:5,en:"We found the corporation powerful.",kr:"우리는 그 기업이 강력하다고 느꼈다."}]},
  "corpulent": {img:"🍔", ex5:[{t:1,en:"The corpulent man eased into a wide chair.",kr:"그 뚱뚱한 남자는 넓은 의자에 천천히 앉았다."},{t:2,en:"Years of feasting left him corpulent.",kr:"여러 해의 잔치가 그를 비대하게 만들었다."},{t:3,en:"The corpulent cat barely moved all day.",kr:"그 뚱뚱한 고양이는 하루 종일 거의 움직이지 않았다."},{t:4,en:"He was once lean, now quite corpulent.",kr:"그는 한때 날씬했으나 지금은 꽤 비대해졌다."},{t:5,en:"The portrait showed a corpulent old judge.",kr:"그 초상화는 뚱뚱한 늙은 판사를 담고 있었다."}]},
  "corral": {img:"🐎", ex5:[{t:1,en:"They worked to corral the loose horses.",kr:"그들은 풀려난 말들을 우리에 몰아넣으려 했다."},{t:2,en:"He tried to corral the noisy kids.",kr:"그는 시끄러운 아이들을 한데 모으려 했다."},{t:3,en:"Staff corralled the crowd to one gate.",kr:"직원들은 군중을 한 출구로 몰았다."},{t:4,en:"She corralled the data into one file.",kr:"그녀는 데이터를 한 파일로 끌어모았다."},{t:5,en:"The dog helped corral the sheep.",kr:"그 개는 양들을 모는 것을 도왔다."}]},
  "correct": {img:"✔️", ex5:[{t:1,en:"Teachers correct tests.",kr:"교사들은 시험을 채점한다."},{t:2,en:"The answer is correct.",kr:"그 답은 정확하다."},{t:3,en:"We correct the error.",kr:"우리는 오류를 바로잡는다."},{t:4,en:"The key gave us the correct answer.",kr:"그 정답지는 우리에게 맞는 답을 알려주었다."},{t:5,en:"We correct the typo quick.",kr:"우리는 그 오타를 재빨리 고친다."}]},
  "correction": {img:"✏️", ex5:[{t:1,en:"A correction posted.",kr:"정정 보도가 났다."},{t:2,en:"The correction is minor.",kr:"그 정정은 사소하다."},{t:3,en:"We made a correction.",kr:"우리는 수정을 했다."},{t:4,en:"The editor gave us a correction.",kr:"그 편집자는 우리에게 수정 사항을 주었다."},{t:5,en:"We found the correction needed.",kr:"우리는 그 수정이 필요함을 알았다."}]},
  "correctly": {img:"💯", ex5:[{t:1,en:"He answered correctly.",kr:"그는 정확히 답했다."},{t:2,en:"The form is filled correctly.",kr:"그 양식은 정확히 작성되었다."},{t:3,en:"We did it correctly.",kr:"우리는 그것을 제대로 했다."},{t:4,en:"It correctly gave us the result.",kr:"그것은 우리에게 정확히 결과를 주었다."},{t:5,en:"We found it spelled correctly.",kr:"우리는 그것이 맞게 쓰인 것을 알았다."}]},
