  "correspond": {img:"✉️", ex5:[{t:1,en:"Pen pals correspond.",kr:"펜팔들은 편지를 주고받는다."},{t:2,en:"The numbers are corresponding.",kr:"그 숫자들이 서로 일치하고 있다."},{t:3,en:"We correspond by mail.",kr:"우리는 우편으로 연락한다."},{t:4,en:"The chart gave us values that correspond.",kr:"그 도표는 우리에게 서로 대응하는 값을 주었다."},{t:5,en:"We correspond often warm.",kr:"우리는 자주 다정히 서신을 주고받는다."}]},
  "corresponding": {img:"🔗", ex5:[{t:1,en:"Each part has a corresponding key.",kr:"각 부분에는 대응하는 키가 있다."},{t:2,en:"The corresponding row is empty.",kr:"그 대응되는 행은 비어 있다."},{t:3,en:"We matched corresponding pairs.",kr:"우리는 대응되는 짝을 맞췄다."},{t:4,en:"The chart gave us corresponding figures.",kr:"그 도표는 우리에게 대응되는 수치를 주었다."},{t:5,en:"We found the corresponding entry.",kr:"우리는 대응되는 항목을 찾았다."}]},
  "corridor": {img:"🚪", ex5:[{t:1,en:"The corridor echoed.",kr:"복도가 울렸다."},{t:2,en:"The corridor is long.",kr:"그 복도는 길다."},{t:3,en:"We walked the corridor.",kr:"우리는 복도를 걸었다."},{t:4,en:"The hotel gave us a quiet corridor.",kr:"그 호텔은 우리에게 조용한 복도를 안겼다."},{t:5,en:"We found the corridor dim.",kr:"우리는 그 복도가 어둑하다고 느꼈다."}]},
  "corroborate": {img:"✅", ex5:[{t:1,en:"Two witnesses corroborated her story.",kr:"두 증인이 그녀의 이야기를 뒷받침했다."},{t:2,en:"New data corroborated the theory.",kr:"새 자료가 그 이론을 입증했다."},{t:3,en:"His account was corroborated by others.",kr:"그의 진술은 다른 이들에 의해 확인되었다."},{t:4,en:"The photos corroborate the claim.",kr:"그 사진들이 그 주장을 뒷받침한다."},{t:5,en:"Facts corroborated what she had said.",kr:"사실들이 그녀가 한 말을 입증했다."}]},
  "corroboration": {img:"✅", ex5:[{t:1,en:"The witness provided corroboration of the story.",kr:"그 목격자가 이야기의 입증을 제공했다."},{t:2,en:"The claim lacked any corroboration.",kr:"그 주장에는 어떤 입증도 없었다."},{t:3,en:"Independent corroboration strengthened the case.",kr:"독립적인 입증이 그 사건을 더 탄탄하게 했다."},{t:4,en:"They sought corroboration from other sources.",kr:"그들은 다른 출처에서 입증을 구했다."},{t:5,en:"The data offered strong corroboration.",kr:"그 데이터가 강력한 입증을 제공했다."}]},
  "corrosion": {img:"🦠", ex5:[{t:1,en:"Salt water causes corrosion of metal.",kr:"소금물은 금속의 부식을 일으킨다."},{t:2,en:"Rust is a common form of corrosion.",kr:"녹은 흔한 형태의 부식이다."},{t:3,en:"They coated the pipes to prevent corrosion.",kr:"그들은 부식을 막으려고 파이프에 코팅을 했다."},{t:4,en:"Corrosion weakened the old bridge.",kr:"부식이 그 낡은 다리를 약화시켰다."},{t:5,en:"Regular maintenance slows down corrosion.",kr:"정기적인 정비는 부식을 늦춘다."}]},
  "corrupt": {img:"💸", ex5:[{t:1,en:"Corrupt officials lie.",kr:"부패한 관리들은 거짓말한다."},{t:2,en:"The file is corrupt.",kr:"그 파일은 손상되었다."},{t:3,en:"We exposed corrupt deals.",kr:"우리는 부패한 거래를 폭로했다."},{t:4,en:"Greed gave us a corrupt system.",kr:"탐욕은 우리에게 부패한 체계를 안겼다."},{t:5,en:"We found the data corrupt.",kr:"우리는 그 데이터가 손상된 것을 알았다."}]},
  "corruption": {img:"🤥", ex5:[{t:1,en:"Corruption spread.",kr:"부패가 퍼졌다."},{t:2,en:"The corruption is deep.",kr:"그 부패는 깊다."},{t:3,en:"We fought corruption.",kr:"우리는 부패에 맞섰다."},{t:4,en:"The probe gave us corruption proof.",kr:"그 수사는 우리에게 부패 증거를 안겼다."},{t:5,en:"We found the corruption widespread.",kr:"우리는 그 부패가 만연함을 알았다."}]},
  "cosmopolitan": {img:"🌍", ex5:[{t:1,en:"London is a truly cosmopolitan city.",kr:"런던은 진정으로 국제적인 도시이다."},{t:2,en:"She has a cosmopolitan outlook on life.",kr:"그녀는 삶에 대한 세계적인 시야를 지녔다."},{t:3,en:"The cafe drew a cosmopolitan crowd.",kr:"그 카페는 다국적의 손님들을 끌어모았다."},{t:4,en:"His cosmopolitan tastes span many cultures.",kr:"그의 국제적인 취향은 여러 문화를 아우른다."},{t:5,en:"They enjoyed the cosmopolitan vibe of the port.",kr:"그들은 그 항구의 국제적인 분위기를 즐겼다."}]},
