  "dazzle": {img:"✨", ex5:[{t:1,en:"The bright lights dazzled the driver.",kr:"밝은 불빛이 운전자의 눈을 부시게 했다."},{t:2,en:"Her talent dazzled the judges.",kr:"그녀의 재능이 심사위원들을 눈부시게 했다."},{t:3,en:"The fireworks dazzled the crowd.",kr:"불꽃놀이가 군중을 황홀하게 했다."},{t:4,en:"The sun on the snow dazzled our eyes.",kr:"눈 위의 햇빛이 우리 눈을 부시게 했다."},{t:5,en:"The dancer dazzled everyone with her grace.",kr:"그 무용수는 우아함으로 모두를 매료시켰다."}]},
  "dazzling": {img:"✨", ex5:[{t:1,en:"The dazzling lights filled the stage.",kr:"눈부신 조명이 무대를 가득 채웠다."},{t:2,en:"She wore a dazzling white gown.",kr:"그녀는 눈부신 흰 가운을 입었다."},{t:3,en:"His dazzling smile won the crowd.",kr:"그의 눈부신 미소가 군중을 사로잡았다."},{t:4,en:"The dazzling sun made us squint.",kr:"눈부신 해가 우리를 눈 찡그리게 했다."},{t:5,en:"It was a dazzling display of skill.",kr:"그것은 눈부신 기량의 향연이었다."}]},
  "deactivation": {img:"🔌", ex5:[{t:1,en:"The deactivation of the alarm took a moment.",kr:"경보의 해제에는 잠깐의 시간이 걸렸다."},{t:2,en:"He requested the deactivation of his account.",kr:"그는 자기 계정의 비활성화를 요청했다."},{t:3,en:"The deactivation of the device saved power.",kr:"그 장치의 비활성화가 전력을 절약했다."},{t:4,en:"Deactivation of the enzyme stopped the reaction.",kr:"그 효소의 불활성화가 반응을 멈췄다."},{t:5,en:"The system confirmed the deactivation.",kr:"그 시스템이 비활성화를 확인했다."}]},
  "dead": {img:"💀", ex5:[{t:1,en:"The plant is dead.",kr:"그 식물은 죽었다."},{t:2,en:"The battery is dead.",kr:"그 배터리는 다 됐다."},{t:3,en:"We found the engine dead.",kr:"우리는 엔진이 멈춘 것을 알았다."},{t:4,en:"The drought gave us dead fields.",kr:"그 가뭄은 우리에게 메마른 들판을 안겼다."},{t:5,en:"We found the line dead.",kr:"우리는 그 전화선이 끊긴 것을 알았다."}]},
