  "declivity": {img:"⛰️", ex5:[{t:1,en:"The path ran down a gentle declivity.",kr:"그 길은 완만한 내리막을 따라 이어졌다."},{t:2,en:"Rain ran fast down the steep declivity.",kr:"빗물이 가파른 비탈을 따라 빠르게 흘렀다."},{t:3,en:"They camped at the foot of the declivity.",kr:"그들은 그 비탈 아래에 야영했다."},{t:4,en:"The declivity made the climb easier going down.",kr:"그 내리막은 내려가는 길을 더 수월하게 했다."},{t:5,en:"A grassy declivity led to the river.",kr:"풀이 우거진 비탈이 강으로 이어졌다."}]},
  "decorate": {img:"🎀", ex5:[{t:1,en:"We decorate the tree.",kr:"우리는 나무를 장식한다."},{t:2,en:"The hall is decorating up.",kr:"그 홀이 꾸며지고 있다."},{t:3,en:"We decorate the room.",kr:"우리는 방을 꾸민다."},{t:4,en:"The kit gave us a way to decorate it.",kr:"그 키트는 우리에게 그것을 꾸밀 방법을 주었다."},{t:5,en:"We decorate the cake pretty.",kr:"우리는 케이크를 예쁘게 장식한다."}]},
  "decoration": {img:"✨", ex5:[{t:1,en:"The decoration shone.",kr:"장식이 빛났다."},{t:2,en:"The decoration is festive.",kr:"그 장식은 흥겹다."},{t:3,en:"We hung the decoration.",kr:"우리는 장식을 걸었다."},{t:4,en:"The shop gave us decorations.",kr:"그 가게는 우리에게 장식품을 주었다."},{t:5,en:"We found the decoration lovely.",kr:"우리는 그 장식이 아름답다고 느꼈다."}]},
  "decorous": {img:"🎩", ex5:[{t:1,en:"The guests kept a decorous silence.",kr:"손님들은 예의 바른 침묵을 지켰다."},{t:2,en:"Her decorous manner suited the event.",kr:"그녀의 점잖은 태도는 그 행사에 잘 어울렸다."},{t:3,en:"He gave a decorous bow to the judge.",kr:"그는 판사에게 예의 바른 인사를 했다."},{t:4,en:"The ceremony was solemn and decorous.",kr:"그 의식은 엄숙하고 격식 있었다."},{t:5,en:"They behaved in a decorous fashion.",kr:"그들은 예의 바른 태도로 행동했다."}]},
  "decorum": {img:"🎩", ex5:[{t:1,en:"The guests behaved with perfect decorum.",kr:"손님들은 완벽한 예의범절로 행동했다."},{t:2,en:"He maintained decorum during the dispute.",kr:"그는 논쟁 중에도 품위를 유지했다."},{t:3,en:"Court decorum demands quiet and respect.",kr:"법정 예절은 정숙과 존중을 요구한다."},{t:4,en:"She praised the students' decorum.",kr:"그녀는 학생들의 예의범절을 칭찬했다."},{t:5,en:"The ceremony required strict decorum.",kr:"그 의식은 엄격한 예법을 요구했다."}]},
  "decoy": {img:"🦆", ex5:[{t:1,en:"The hunter set a wooden decoy on the still pond.",kr:"사냥꾼은 고요한 연못에 나무 미끼 오리를 놓았다."},{t:2,en:"The fake truck was a decoy to fool the enemy.",kr:"그 가짜 트럭은 적을 속이기 위한 미끼였다."},{t:3,en:"Police used a decoy to draw out the thief.",kr:"경찰은 도둑을 꾀어내려 미끼를 사용했다."},{t:4,en:"The bright sign was just a decoy for the real shop.",kr:"그 밝은 간판은 진짜 가게를 위한 눈속임일 뿐이었다."},{t:5,en:"Birds landed near the floating decoy.",kr:"새들이 떠 있는 미끼 근처에 내려앉았다."}]},
  "decrease": {img:"📉", ex5:[{t:1,en:"Prices decrease.",kr:"가격이 내려간다."},{t:2,en:"The rate is decreasing.",kr:"그 수치가 감소하고 있다."},{t:3,en:"We decrease the dose.",kr:"우리는 복용량을 줄인다."},{t:4,en:"The plan gave us a decrease.",kr:"그 계획은 우리에게 감소를 안겼다."},{t:5,en:"We found the decrease steady.",kr:"우리는 그 감소가 꾸준하다고 보았다."}]},
