  "difference": {img:"➗", ex5:[{t:1,en:"The difference is small.",kr:"그 차이는 작다."},{t:2,en:"The difference grew.",kr:"그 차이가 커졌다."},{t:3,en:"We noted the difference.",kr:"우리는 그 차이를 주목했다."},{t:4,en:"The test gave us a difference.",kr:"그 검사는 우리에게 차이를 보여주었다."},{t:5,en:"We found the difference clear.",kr:"우리는 그 차이가 분명하다고 느꼈다."}]},
  "differences": {img:"🔀", ex5:[{t:1,en:"Differences remain.",kr:"차이가 남아 있다."},{t:2,en:"The differences are minor.",kr:"그 차이들은 사소하다."},{t:3,en:"We resolved our differences.",kr:"우리는 이견을 좁혔다."},{t:4,en:"The chart gave us the differences.",kr:"그 도표는 우리에게 차이들을 보여주었다."},{t:5,en:"We found the differences slight.",kr:"우리는 그 차이들이 미미하다고 느꼈다."}]},
  "different": {img:"🎨", ex5:[{t:1,en:"Each one is different.",kr:"각각이 다르다."},{t:2,en:"The view is different.",kr:"그 견해는 다르다."},{t:3,en:"We tried a different way.",kr:"우리는 다른 방법을 시도했다."},{t:4,en:"The trip gave us a different view.",kr:"그 여행은 우리에게 색다른 관점을 안겼다."},{t:5,en:"We found the result different.",kr:"우리는 그 결과가 다르다고 느꼈다."}]},
