  "difficulty": {img:"⚠️", ex5:[{t:1,en:"Difficulty arose.",kr:"어려움이 생겼다."},{t:2,en:"The difficulty is high.",kr:"그 난이도는 높다."},{t:3,en:"We faced difficulty.",kr:"우리는 어려움에 부딪혔다."},{t:4,en:"The task gave us difficulty.",kr:"그 과제는 우리에게 난관을 안겼다."},{t:5,en:"We found the difficulty manageable.",kr:"우리는 그 어려움이 감당할 만하다고 느꼈다."}]},
  "diffidence": {img:"😟", ex5:[{t:1,en:"He spoke with shy diffidence.",kr:"그는 수줍은 자신 없음으로 말했다."},{t:2,en:"Her diffidence hid real talent.",kr:"그녀의 소심함은 진짜 재능을 감추고 있었다."},{t:3,en:"Years of practice cured his diffidence.",kr:"여러 해의 연습이 그의 소심함을 고쳤다."},{t:4,en:"She answered with surprising diffidence.",kr:"그녀는 뜻밖의 머뭇거림으로 답했다."},{t:5,en:"His diffidence faded once he relaxed.",kr:"그가 긴장을 풀자 소심함이 사라졌다."}]},
  "diffident": {img:"😳", ex5:[{t:1,en:"She was diffident about speaking up.",kr:"그녀는 나서서 말하기를 수줍어했다."},{t:2,en:"His diffident smile hid his skill.",kr:"그의 수줍은 미소가 솜씨를 감췄다."},{t:3,en:"The diffident boy stayed in the back.",kr:"그 수줍은 소년은 뒤쪽에 있었다."},{t:4,en:"She gave a diffident little wave.",kr:"그녀는 수줍게 작게 손을 흔들었다."},{t:5,en:"He grew less diffident over time.",kr:"그는 시간이 지나며 덜 수줍어졌다."}]},
