  "digital": {img:"💻", ex5:[{t:1,en:"The world is digital.",kr:"세상은 디지털이다."},{t:2,en:"The clock is digital.",kr:"그 시계는 디지털이다."},{t:3,en:"We went digital.",kr:"우리는 디지털로 전환했다."},{t:4,en:"The firm gave us a digital tool.",kr:"그 회사는 우리에게 디지털 도구를 주었다."},{t:5,en:"We found the digital copy clear.",kr:"우리는 그 디지털 사본이 선명하다고 느꼈다."}]},
  "dignity": {img:"🎩", ex5:[{t:1,en:"Dignity matters.",kr:"존엄은 중요하다."},{t:2,en:"Her dignity is intact.",kr:"그녀의 품위는 온전하다."},{t:3,en:"We kept our dignity.",kr:"우리는 품위를 지켰다."},{t:4,en:"The act gave us dignity.",kr:"그 행동은 우리에게 존엄을 안겼다."},{t:5,en:"We found the dignity moving.",kr:"우리는 그 품위가 감동적이라고 느꼈다."}]},
  "dilapidated": {img:"🏚️", ex5:[{t:1,en:"They lived in a dilapidated old house.",kr:"그들은 다 허물어져 가는 낡은 집에 살았다."},{t:2,en:"The dilapidated barn was about to fall.",kr:"그 다 쓰러져 가는 헛간은 곧 무너질 듯했다."},{t:3,en:"The road was cracked and dilapidated.",kr:"그 길은 금이 가고 황폐했다."},{t:4,en:"They fixed the dilapidated fence.",kr:"그들은 다 망가진 울타리를 고쳤다."},{t:5,en:"The dilapidated shop closed long ago.",kr:"그 다 허물어진 가게는 오래전에 문을 닫았다."}]},
