  "dilatory": {img:"🐌", ex5:[{t:1,en:"His dilatory replies cost them time.",kr:"그의 느릿한 답변이 그들의 시간을 허비시켰다."},{t:2,en:"They used dilatory tactics to delay.",kr:"그들은 지연시키려고 시간 끌기 전술을 썼다."},{t:3,en:"Her dilatory habits frustrated the team.",kr:"꾸물대는 그녀의 습관이 팀을 답답하게 했다."},{t:4,en:"A dilatory clerk slowed the line.",kr:"굼뜬 직원이 줄을 더디게 했다."},{t:5,en:"Stop being dilatory and finish.",kr:"꾸물대지 말고 끝내라."}]},
  "dilemma": {img:"🤷", ex5:[{t:1,en:"A dilemma arose.",kr:"딜레마가 생겼다."},{t:2,en:"The dilemma is tough.",kr:"그 딜레마는 까다롭다."},{t:3,en:"We faced a dilemma.",kr:"우리는 딜레마에 처했다."},{t:4,en:"The case gave us a dilemma.",kr:"그 사건은 우리에게 딜레마를 안겼다."},{t:5,en:"We found the dilemma hard.",kr:"우리는 그 딜레마가 어렵다고 느꼈다."}]},
  "diligence": {img:"📖", ex5:[{t:1,en:"Her diligence earned the team's respect.",kr:"그녀의 근면함이 팀의 존경을 얻었다."},{t:2,en:"He completed the task with great diligence.",kr:"그는 대단한 성실함으로 그 일을 마쳤다."},{t:3,en:"Diligence and patience led to success.",kr:"근면과 인내가 성공으로 이어졌다."},{t:4,en:"The lawyer praised the clerk's diligence.",kr:"그 변호사는 사무원의 성실함을 칭찬했다."},{t:5,en:"Years of diligence built her fine reputation.",kr:"여러 해의 근면이 그녀의 훌륭한 명성을 쌓았다."}]},
