  "diligently": {img:"📚", ex5:[{t:1,en:"She studied diligently for the exam.",kr:"그녀는 시험을 위해 부지런히 공부했다."},{t:2,en:"He worked diligently from dawn to dusk.",kr:"그는 새벽부터 해 질 녘까지 부지런히 일했다."},{t:3,en:"The team searched diligently for the cause.",kr:"그 팀은 원인을 부지런히 찾았다."},{t:4,en:"They saved money diligently each month.",kr:"그들은 다달이 부지런히 돈을 모았다."},{t:5,en:"The clerk checked each form diligently.",kr:"그 직원은 각 서류를 꼼꼼히 점검했다."}]},
  "dim": {img:"🔅", ex5:[{t:1,en:"The light is dim.",kr:"불빛이 어둑하다."},{t:2,en:"The room is dim.",kr:"그 방은 어둑하다."},{t:3,en:"We dim the lamp.",kr:"우리는 등불을 낮춘다."},{t:4,en:"The dusk gave us a dim glow.",kr:"그 황혼은 우리에게 어둑한 빛을 안겼다."},{t:5,en:"We found the hall dim.",kr:"우리는 그 복도가 어둑하다고 느꼈다."}]},
  "dimension": {img:"📐", ex5:[{t:1,en:"The dimension shifted.",kr:"차원이 바뀌었다."},{t:2,en:"The dimension is key.",kr:"그 측면은 핵심이다."},{t:3,en:"We measured each dimension.",kr:"우리는 각 치수를 쟀다."},{t:4,en:"The plan gave us a new dimension.",kr:"그 계획은 우리에게 새로운 차원을 안겼다."},{t:5,en:"We found the dimension wrong.",kr:"우리는 그 치수가 틀린 것을 알았다."}]},
  "diminish": {img:"📉", ex5:[{t:1,en:"Stocks diminish.",kr:"재고가 줄어든다."},{t:2,en:"The pain is diminishing.",kr:"그 통증이 줄고 있다."},{t:3,en:"We diminish the risk.",kr:"우리는 위험을 줄인다."},{t:4,en:"The plan gave us a way to diminish it.",kr:"그 계획은 우리에게 그것을 줄일 방법을 주었다."},{t:5,en:"We diminish the waste fast.",kr:"우리는 그 낭비를 빠르게 줄인다."}]},
  "dine": {img:"🍽️", ex5:[{t:1,en:"Guests dine here.",kr:"손님들은 여기서 식사한다."},{t:2,en:"The couple is dining.",kr:"그 커플이 식사하고 있다."},{t:3,en:"We dine at eight.",kr:"우리는 여덟 시에 저녁을 먹는다."},{t:4,en:"The inn gave us a place to dine.",kr:"그 여관은 우리에게 식사할 곳을 주었다."},{t:5,en:"We dine in style fine.",kr:"우리는 멋지게 식사한다."}]},
  "dinghy": {img:"🚣", ex5:[{t:1,en:"They rowed the dinghy to the shore.",kr:"그들은 작은 보트를 저어 해안으로 갔다."},{t:2,en:"The dinghy bobbed beside the yacht.",kr:"그 작은 보트가 요트 옆에서 까닥거렸다."},{t:3,en:"He inflated the rubber dinghy.",kr:"그는 고무보트에 바람을 넣었다."},{t:4,en:"A small dinghy carried them to land.",kr:"작은 보트가 그들을 육지로 실어 날랐다."},{t:5,en:"The dinghy was tied to the dock.",kr:"그 작은 보트는 부두에 매여 있었다."}]},
  "dingy": {img:"🏚️", ex5:[{t:1,en:"They lived in a dingy little room.",kr:"그들은 칙칙한 작은 방에서 살았다."},{t:2,en:"The dingy walls needed fresh paint.",kr:"그 칙칙한 벽은 새 페인트가 필요했다."},{t:3,en:"The old curtains looked dingy.",kr:"그 낡은 커튼은 칙칙해 보였다."},{t:4,en:"A dingy lamp lit the corner.",kr:"칙칙한 등 하나가 구석을 밝혔다."},{t:5,en:"The dingy alley felt gloomy.",kr:"그 우중충한 골목은 음울하게 느껴졌다."}]},
  "dinner": {img:"🍲", ex5:[{t:1,en:"Dinner is ready.",kr:"저녁이 준비됐다."},{t:2,en:"The dinner is warm.",kr:"그 저녁은 따뜻하다."},{t:3,en:"We cooked dinner.",kr:"우리는 저녁을 요리했다."},{t:4,en:"Mom gave us dinner.",kr:"엄마는 우리에게 저녁을 차려 주셨다."},{t:5,en:"We found the dinner tasty.",kr:"우리는 그 저녁이 맛있다고 느꼈다."}]},
  "dinosaur": {img:"🦕", ex5:[{t:1,en:"The dinosaur roared.",kr:"공룡이 포효했다."},{t:2,en:"The dinosaur is huge.",kr:"그 공룡은 거대하다."},{t:3,en:"We saw a dinosaur model.",kr:"우리는 공룡 모형을 보았다."},{t:4,en:"The museum gave us a dinosaur tour.",kr:"그 박물관은 우리에게 공룡 견학을 제공했다."},{t:5,en:"We found the dinosaur amazing.",kr:"우리는 그 공룡이 놀랍다고 느꼈다."}]},
  "diode": {img:"💡", ex5:[{t:1,en:"A diode lets current flow in one direction.",kr:"다이오드는 전류가 한 방향으로만 흐르게 한다."},{t:2,en:"The circuit uses a diode to block reverse current.",kr:"그 회로는 역전류를 막기 위해 다이오드를 사용한다."},{t:3,en:"A light-emitting diode glows when powered.",kr:"발광 다이오드는 전원이 들어오면 빛난다."},{t:4,en:"He replaced the burnt-out diode.",kr:"그는 타버린 다이오드를 교체했다."},{t:5,en:"Each diode was soldered onto the board.",kr:"각 다이오드는 기판에 납땜되었다."}]},
  "diorama": {img:"🏞️", ex5:[{t:1,en:"The students built a diorama of a rain forest.",kr:"학생들은 열대우림의 디오라마를 만들었다."},{t:2,en:"A small diorama showed the battle in miniature.",kr:"작은 디오라마가 그 전투를 축소 모형으로 보여 주었다."},{t:3,en:"The museum's diorama recreated an ancient village.",kr:"박물관의 디오라마는 고대 마을을 재현했다."},{t:4,en:"Tiny figures stood inside the glass diorama.",kr:"작은 인형들이 유리 디오라마 안에 서 있었다."},{t:5,en:"Light made the diorama look almost real.",kr:"조명이 그 디오라마를 거의 진짜처럼 보이게 했다."}]},
  "dip": {img:"🥣", ex5:[{t:1,en:"Prices dip.",kr:"가격이 살짝 내려간다."},{t:2,en:"The road dips.",kr:"길이 움푹 내려간다."},{t:3,en:"We dip the chips.",kr:"우리는 칩을 소스에 찍는다."},{t:4,en:"The party gave us a tasty dip.",kr:"그 파티는 우리에게 맛있는 소스를 안겼다."},{t:5,en:"We dip the brush light.",kr:"우리는 붓을 살짝 담근다."}]},
  "diploma": {img:"🎓", ex5:[{t:1,en:"The diploma arrived.",kr:"졸업장이 도착했다."},{t:2,en:"The diploma is framed.",kr:"그 졸업장은 액자에 담겼다."},{t:3,en:"We earned a diploma.",kr:"우리는 졸업장을 받았다."},{t:4,en:"The school gave us a diploma.",kr:"학교는 우리에게 졸업장을 수여했다."},{t:5,en:"We found the diploma proud.",kr:"우리는 그 졸업장이 자랑스럽다고 느꼈다."}]},
  "diplomacy": {img:"🤝", ex5:[{t:1,en:"They solved the dispute through diplomacy.",kr:"그들은 외교로 그 분쟁을 해결했다."},{t:2,en:"Good diplomacy can prevent war.",kr:"좋은 외교는 전쟁을 막을 수 있다."},{t:3,en:"She handled the issue with diplomacy.",kr:"그녀는 그 문제를 외교적으로 처리했다."},{t:4,en:"Diplomacy requires patience and tact.",kr:"외교는 인내와 요령이 필요하다."},{t:5,en:"The two nations chose diplomacy over force.",kr:"그 두 나라는 무력 대신 외교를 택했다."}]},
