  "dwell": {img:"🏠", ex5:[{t:1,en:"Owls dwell in trees.",kr:"올빼미는 나무에 산다."},{t:2,en:"The mind is dwelling on it.",kr:"마음이 그것에 머물러 있다."},{t:3,en:"We dwell near the lake.",kr:"우리는 호수 가까이 산다."},{t:4,en:"The cave gave us a place to dwell.",kr:"그 동굴은 우리에게 머물 곳을 주었다."},{t:5,en:"We dwell on the past none.",kr:"우리는 과거에 전혀 연연하지 않는다."}]},
  "dweller": {img:"🏙️", ex5:[{t:1,en:"A city dweller often misses the quiet of nature.",kr:"도시 거주자는 흔히 자연의 고요함을 그리워한다."},{t:2,en:"The cave dweller painted on the rock walls.",kr:"그 동굴 거주자가 바위 벽에 그림을 그렸다."},{t:3,en:"Each dweller paid rent to the landlord.",kr:"각 거주자가 집주인에게 임대료를 냈다."},{t:4,en:"A forest dweller knows every trail.",kr:"숲에 사는 사람은 모든 오솔길을 안다."},{t:5,en:"The apartment dweller kept plants on the balcony.",kr:"그 아파트 거주자는 발코니에 식물을 길렀다."}]},
  "dwelling": {img:"🛖", ex5:[{t:1,en:"The dwelling stood firm.",kr:"그 거처는 굳건히 서 있었다."},{t:2,en:"The dwelling is small.",kr:"그 주거지는 작다."},{t:3,en:"We entered the dwelling.",kr:"우리는 그 거처에 들어갔다."},{t:4,en:"The land gave us a dwelling.",kr:"그 땅은 우리에게 거처를 마련해 주었다."},{t:5,en:"We found the dwelling cozy.",kr:"우리는 그 거처가 아늑하다고 느꼈다."}]},
  "dwindle": {img:"📉", ex5:[{t:1,en:"Their supplies began to dwindle.",kr:"그들의 물자가 줄어들기 시작했다."},{t:2,en:"The crowd dwindled as it grew late.",kr:"늦어지면서 군중이 줄어들었다."},{t:3,en:"His savings slowly dwindled.",kr:"그의 저축이 서서히 줄어들었다."},{t:4,en:"The fire dwindled to a few coals.",kr:"불이 잉걸불 몇 개로 사그라들었다."},{t:5,en:"Hope dwindled as days passed.",kr:"날이 갈수록 희망이 줄어들었다."}]},
  "dye": {img:"🎨", ex5:[{t:1,en:"We dye the cloth.",kr:"우리는 천을 염색한다."},{t:2,en:"The dye is bright.",kr:"그 염료는 선명하다."},{t:3,en:"We dye the hair.",kr:"우리는 머리를 염색한다."},{t:4,en:"The kit gave us a red dye.",kr:"그 키트는 우리에게 빨간 염료를 주었다."},{t:5,en:"We found the dye permanent.",kr:"우리는 그 염료가 잘 안 빠진다고 느꼈다."}]},
  "dynamic": {img:"⚡", ex5:[{t:1,en:"The market is dynamic.",kr:"그 시장은 역동적이다."},{t:2,en:"The team is dynamic.",kr:"그 팀은 활기차다."},{t:3,en:"We built a dynamic page.",kr:"우리는 동적인 페이지를 만들었다."},{t:4,en:"The app gave us a dynamic view.",kr:"그 앱은 우리에게 동적인 화면을 주었다."},{t:5,en:"We found the duo dynamic.",kr:"우리는 그 듀오가 역동적이라고 느꼈다."}]},
  "dynamo": {img:"⚡", ex5:[{t:1,en:"The old bicycle had a dynamo to power its lamp.",kr:"그 오래된 자전거에는 전등을 밝힐 발전기가 있었다."},{t:2,en:"A small dynamo turned the river's flow into power.",kr:"작은 발전기가 강의 흐름을 전력으로 바꾸었다."},{t:3,en:"The young coach was a real dynamo of energy.",kr:"그 젊은 코치는 진정한 활력 넘치는 사람이었다."},{t:4,en:"The factory ran on a steam-driven dynamo.",kr:"그 공장은 증기로 돌아가는 발전기로 가동되었다."},{t:5,en:"She is the dynamo behind the whole project.",kr:"그녀는 그 프로젝트 전체를 움직이는 원동력이다."}]},
  "dynasty": {img:"👑", ex5:[{t:1,en:"The dynasty fell.",kr:"그 왕조가 무너졌다."},{t:2,en:"The dynasty is ancient.",kr:"그 왕조는 고대의 것이다."},{t:3,en:"We studied the dynasty.",kr:"우리는 그 왕조를 공부했다."},{t:4,en:"History gave us a dynasty tale.",kr:"역사는 우리에게 왕조 이야기를 안겼다."},{t:5,en:"We found the dynasty mighty.",kr:"우리는 그 왕조가 강성했다고 느꼈다."}]},
  "each": {img:"☝️", ex5:[{t:1,en:"Each student received a book.",kr:"각 학생이 책을 한 권씩 받았다."},{t:2,en:"They greeted each other warmly.",kr:"그들은 서로 따뜻하게 인사했다."},{t:3,en:"Each room has its own window.",kr:"각 방에는 저마다 창문이 있다."},{t:4,en:"The tickets cost ten dollars each.",kr:"그 표는 한 장에 10달러다."},{t:5,en:"Each day brings something new.",kr:"하루하루 새로운 것을 가져다준다."}]},
  "eager": {img:"😀", ex5:[{t:1,en:"The kids are eager.",kr:"아이들은 열의에 차 있다."},{t:2,en:"The fans are eager.",kr:"팬들은 간절하다."},{t:3,en:"We are eager to start.",kr:"우리는 시작하고 싶어 안달이다."},{t:4,en:"The news gave us an eager mood.",kr:"그 소식은 우리에게 들뜬 기분을 안겼다."},{t:5,en:"We found the team eager.",kr:"우리는 그 팀이 열의에 찼다고 느꼈다."}]},
  "eagerly": {img:"🤩", ex5:[{t:1,en:"She waited eagerly.",kr:"그녀는 간절히 기다렸다."},{t:2,en:"The crowd cheered eagerly.",kr:"군중이 열렬히 환호했다."},{t:3,en:"We eagerly joined in.",kr:"우리는 열성적으로 참여했다."},{t:4,en:"It eagerly gave us hope.",kr:"그것은 우리에게 간절한 희망을 주었다."},{t:5,en:"We found them waiting eagerly.",kr:"우리는 그들이 간절히 기다림을 알았다."}]},
