  "earnest": {img:"🙂", ex5:[{t:1,en:"She made an earnest effort to help.",kr:"그녀는 도우려고 진지한 노력을 기울였다."},{t:2,en:"He spoke in an earnest voice.",kr:"그는 진지한 목소리로 말했다."},{t:3,en:"Their earnest hope was for peace.",kr:"그들의 진실한 바람은 평화였다."},{t:4,en:"The work began in earnest.",kr:"그 일이 본격적으로 시작되었다."},{t:5,en:"His earnest words moved the crowd.",kr:"그의 진지한 말이 군중을 감동시켰다."}]},
  "earnestly": {img:"🙏", ex5:[{t:1,en:"He spoke earnestly about his hopes.",kr:"그는 자신의 희망에 대해 진지하게 말했다."},{t:2,en:"She earnestly tried to help.",kr:"그녀는 진심으로 도우려 애썼다."},{t:3,en:"They earnestly begged for more time.",kr:"그들은 더 많은 시간을 간절히 청했다."},{t:4,en:"He worked earnestly on the project.",kr:"그는 그 프로젝트에 진지하게 매달렸다."},{t:5,en:"She listened earnestly to every word.",kr:"그녀는 모든 말을 진지하게 들었다."}]},
  "earnings": {img:"📈", ex5:[{t:1,en:"Earnings rose.",kr:"수익이 올랐다."},{t:2,en:"The earnings are strong.",kr:"그 수익은 견조하다."},{t:3,en:"We reported earnings.",kr:"우리는 실적을 발표했다."},{t:4,en:"The quarter gave us high earnings.",kr:"그 분기는 우리에게 높은 수익을 안겼다."},{t:5,en:"We found the earnings stable.",kr:"우리는 그 수익이 안정적이라고 느꼈다."}]},
  "earth": {img:"🌍", ex5:[{t:1,en:"The earth spins.",kr:"지구는 자전한다."},{t:2,en:"The earth is warm.",kr:"그 흙은 따뜻하다."},{t:3,en:"We protect the earth.",kr:"우리는 지구를 보호한다."},{t:4,en:"The garden gave us rich earth.",kr:"그 정원은 우리에게 비옥한 흙을 안겼다."},{t:5,en:"We found the earth fragile.",kr:"우리는 지구가 연약하다고 느꼈다."}]},
  "earthquake": {img:"🌋", ex5:[{t:1,en:"The earthquake struck.",kr:"지진이 닥쳤다."},{t:2,en:"The earthquake is strong.",kr:"그 지진은 강하다."},{t:3,en:"We survived the earthquake.",kr:"우리는 지진에서 살아남았다."},{t:4,en:"The quake gave us an earthquake drill.",kr:"그 진동은 우리에게 지진 대피 훈련을 떠올리게 했다."},{t:5,en:"We found the earthquake severe.",kr:"우리는 그 지진이 심각하다고 느꼈다."}]},
  "earwig": {img:"🐛", ex5:[{t:1,en:"An earwig crawled out from under the pot.",kr:"집게벌레 한 마리가 화분 밑에서 기어 나왔다."},{t:2,en:"The earwig has pincers at its rear.",kr:"집게벌레는 꽁무니에 집게를 지녔다."},{t:3,en:"She found an earwig in the damp firewood.",kr:"그녀는 축축한 장작에서 집게벌레를 발견했다."},{t:4,en:"An earwig prefers dark, moist places.",kr:"집게벌레는 어둡고 축축한 곳을 선호한다."},{t:5,en:"The earwig scurried away from the light.",kr:"그 집게벌레는 빛을 피해 잽싸게 달아났다."}]},
