  "easel": {img:"🎨", ex5:[{t:1,en:"The artist set the canvas on an easel.",kr:"그 화가는 캔버스를 이젤에 올렸다."},{t:2,en:"An easel stood by the window.",kr:"이젤 하나가 창가에 서 있었다."},{t:3,en:"She adjusted the easel's height.",kr:"그녀는 이젤의 높이를 조절했다."},{t:4,en:"He carried his easel to the park.",kr:"그는 이젤을 공원으로 가져갔다."},{t:5,en:"A small easel held the photo.",kr:"작은 이젤이 그 사진을 받쳐 들고 있었다."}]},
  "easily": {img:"👌", ex5:[{t:1,en:"She wins easily.",kr:"그녀는 쉽게 이긴다."},{t:2,en:"The lid opens easily.",kr:"그 뚜껑은 쉽게 열린다."},{t:3,en:"We solved it easily.",kr:"우리는 그것을 쉽게 풀었다."},{t:4,en:"It easily gave us the win.",kr:"그것은 우리에게 손쉽게 승리를 안겼다."},{t:5,en:"We found it done easily.",kr:"우리는 그것이 수월하게 끝남을 알았다."}]},
  "east": {img:"🧭", ex5:[{t:1,en:"The sun rises in the east.",kr:"해는 동쪽에서 뜬다."},{t:2,en:"The east is bright.",kr:"동쪽이 밝다."},{t:3,en:"We headed east.",kr:"우리는 동쪽으로 향했다."},{t:4,en:"The map gave us an east route.",kr:"그 지도는 우리에게 동쪽 경로를 보여주었다."},{t:5,en:"We found the east calm.",kr:"우리는 동쪽이 고요하다고 느꼈다."}]},
  "eastern": {img:"🌏", ex5:[{t:1,en:"Eastern winds blew.",kr:"동풍이 불었다."},{t:2,en:"The eastern sky glowed.",kr:"동쪽 하늘이 빛났다."},{t:3,en:"We toured the eastern coast.",kr:"우리는 동부 해안을 둘러보았다."},{t:4,en:"The trip gave us eastern views.",kr:"그 여행은 우리에게 동부 풍경을 안겼다."},{t:5,en:"We found the eastern style fresh.",kr:"우리는 그 동양식이 신선하다고 느꼈다."}]},
  "easy": {img:"😊", ex5:[{t:1,en:"The test is easy.",kr:"그 시험은 쉽다."},{t:2,en:"The recipe is easy.",kr:"그 조리법은 쉽다."},{t:3,en:"We took the easy path.",kr:"우리는 쉬운 길을 택했다."},{t:4,en:"The guide gave us an easy start.",kr:"그 안내서는 우리에게 쉬운 출발을 안겼다."},{t:5,en:"We found the task easy.",kr:"우리는 그 일이 쉽다고 느꼈다."}]},
  "eat": {img:"🍴", ex5:[{t:1,en:"We eat lunch.",kr:"우리는 점심을 먹는다."},{t:2,en:"The dog is eating.",kr:"그 개가 먹고 있다."},{t:3,en:"We eat the soup.",kr:"우리는 수프를 먹는다."},{t:4,en:"Mom gave us food to eat.",kr:"엄마는 우리에게 먹을 음식을 주셨다."},{t:5,en:"We eat the meal slow.",kr:"우리는 그 식사를 천천히 먹는다."}]},
  "ebb": {img:"🌊", ex5:[{t:1,en:"The tide began to ebb.",kr:"조수가 빠지기 시작했다."},{t:2,en:"His strength slowly ebbed away.",kr:"그의 기력이 서서히 빠져나갔다."},{t:3,en:"At low ebb, the rocks appear.",kr:"썰물 때 그 바위들이 드러난다."},{t:4,en:"Her hope ebbed as night fell.",kr:"밤이 되자 그녀의 희망이 사그라들었다."},{t:5,en:"The crowd's energy ebbed late in the day.",kr:"늦은 시간이 되자 군중의 활기가 빠져나갔다."}]},
  "ebullience": {img:"🎉", ex5:[{t:1,en:"Her ebullience lifted the whole room.",kr:"그녀의 활기가 방 전체를 들뜨게 했다."},{t:2,en:"He greeted us with warm ebullience.",kr:"그는 따뜻한 활기로 우리를 맞았다."},{t:3,en:"The crowd's ebullience was contagious.",kr:"군중의 활기는 전염성이 있었다."},{t:4,en:"Spring filled her with ebullience.",kr:"봄은 그녀를 생기로 가득 채웠다."},{t:5,en:"His ebullience never seemed to fade.",kr:"그의 활기는 결코 사그라들지 않는 듯했다."}]},
