  "intersection": {img:"🚦", ex5:[{t:1,en:"Turn left at the next intersection.",kr:"다음 교차로에서 좌회전해라."},{t:2,en:"A traffic light stands at the intersection.",kr:"그 교차로에는 신호등이 있다."},{t:3,en:"The accident happened at a busy intersection.",kr:"그 사고는 붐비는 교차로에서 일어났다."},{t:4,en:"Cars waited at the wide intersection.",kr:"차들이 넓은 교차로에서 기다렸다."},{t:5,en:"Cross the intersection only on green.",kr:"초록불일 때만 교차로를 건너라."}]},
  "intertwine": {img:"🔗", ex5:[{t:1,en:"The vines intertwine around the post.",kr:"그 덩굴들이 기둥을 휘감으며 얽힌다."},{t:2,en:"Their lives became intertwined.",kr:"그들의 삶은 서로 얽히게 되었다."},{t:3,en:"She intertwined the ribbons.",kr:"그녀는 리본들을 서로 엮었다."},{t:4,en:"The two stories intertwine cleverly.",kr:"그 두 이야기가 교묘하게 얽힌다."},{t:5,en:"Roots intertwine deep in the soil.",kr:"뿌리들이 흙 속 깊이 서로 얽힌다."}]},
  "interval": {img:"⏱️", ex5:[{t:1,en:"The interval is short.",kr:"그 간격은 짧다."},{t:2,en:"The interval grew.",kr:"그 간격이 길어졌다."},{t:3,en:"We rested at intervals.",kr:"우리는 일정 간격으로 쉬었다."},{t:4,en:"The plan gave us an interval.",kr:"그 계획은 우리에게 휴식 간격을 주었다."},{t:5,en:"We found the interval even.",kr:"우리는 그 간격이 일정하다고 느꼈다."}]},
