  "intervention": {img:"🚑", ex5:[{t:1,en:"The intervention helped.",kr:"그 개입이 도움이 됐다."},{t:2,en:"The intervention is timely.",kr:"그 개입은 시의적절하다."},{t:3,en:"We led the intervention.",kr:"우리는 그 개입을 이끌었다."},{t:4,en:"The team gave us an intervention.",kr:"그 팀은 우리에게 개입 조치를 안겼다."},{t:5,en:"We found the intervention vital.",kr:"우리는 그 개입이 필수적이라고 느꼈다."}]},
  "interview": {img:"🎤", ex5:[{t:1,en:"The interview went well.",kr:"그 면접은 잘 진행됐다."},{t:2,en:"The interview is short.",kr:"그 인터뷰는 짧다."},{t:3,en:"We had an interview.",kr:"우리는 면접을 봤다."},{t:4,en:"The firm gave us an interview.",kr:"그 회사는 우리에게 면접 기회를 주었다."},{t:5,en:"We found the interview tough.",kr:"우리는 그 면접이 까다롭다고 느꼈다."}]},
  "intestate": {img:"📄", ex5:[{t:1,en:"He died intestate, leaving no will.",kr:"그는 유언 없이 사망하여 유언장을 남기지 않았다."},{t:2,en:"When someone dies intestate, the law decides.",kr:"누군가 유언 없이 사망하면 법이 결정한다."},{t:3,en:"The intestate estate was divided among heirs.",kr:"유언 없는 유산은 상속인들에게 분배되었다."},{t:4,en:"Dying intestate can complicate inheritance.",kr:"유언 없이 사망하면 상속이 복잡해질 수 있다."},{t:5,en:"Her father died intestate years ago.",kr:"그녀의 아버지는 여러 해 전 유언 없이 돌아가셨다."}]},
  "intestine": {img:"🫃", ex5:[{t:1,en:"The intestine absorbs food into the body.",kr:"장은 음식을 몸으로 흡수한다."},{t:2,en:"The small intestine is long and coiled.",kr:"소장은 길고 둘둘 말려 있다."},{t:3,en:"Good bacteria live in the intestine.",kr:"유익한 세균이 장 속에 산다."},{t:4,en:"The large intestine stores waste.",kr:"대장은 노폐물을 저장한다."},{t:5,en:"The intestine plays a key role in digestion.",kr:"장은 소화에 핵심 역할을 한다."}]},
  "intimate": {img:"💞", ex5:[{t:1,en:"The talk was intimate.",kr:"그 대화는 친밀했다."},{t:2,en:"The setting is intimate.",kr:"그 분위기는 아늑하다."},{t:3,en:"We shared an intimate moment.",kr:"우리는 친밀한 순간을 나눴다."},{t:4,en:"The dinner gave us an intimate vibe.",kr:"그 만찬은 우리에게 친밀한 분위기를 안겼다."},{t:5,en:"We found the room intimate.",kr:"우리는 그 방이 아늑하다고 느꼈다."}]},
  "intimation": {img:"💬", ex5:[{t:1,en:"He gave no intimation of his plan.",kr:"그는 자기 계획을 전혀 내비치지 않았다."},{t:2,en:"There was an intimation of trouble.",kr:"곤경의 기미가 있었다."},{t:3,en:"Her tone carried an intimation of doubt.",kr:"그녀의 어조에는 의심의 암시가 담겼다."},{t:4,en:"The first intimation came by letter.",kr:"첫 암시는 편지로 왔다."},{t:5,en:"He caught the subtle intimation.",kr:"그는 미묘한 암시를 알아챘다."}]},
  "intimidate": {img:"😠", ex5:[{t:1,en:"They tried to intimidate the witness.",kr:"그들은 그 증인을 위협하려 했다."},{t:2,en:"The big dog intimidated the children.",kr:"그 큰 개가 아이들을 겁먹게 했다."},{t:3,en:"Don't let the test intimidate you.",kr:"그 시험에 겁먹지 마라."},{t:4,en:"His loud voice intimidated the new staff.",kr:"그의 큰 목소리가 신입 직원들을 겁먹게 했다."},{t:5,en:"She refused to be intimidated.",kr:"그녀는 위협당하기를 거부했다."}]},
  "intractable": {img:"🐂", ex5:[{t:1,en:"The dispute proved intractable despite years of talks.",kr:"그 분쟁은 수년간의 협상에도 해결하기 어려운 것으로 드러났다."},{t:2,en:"He faced an intractable problem with no easy answer.",kr:"그는 쉬운 답이 없는 다루기 힘든 문제에 직면했다."},{t:3,en:"The intractable mule refused to move an inch.",kr:"고집 센 노새는 한 치도 움직이려 하지 않았다."},{t:4,en:"Her intractable pain resisted every treatment.",kr:"그녀의 다루기 힘든 통증은 모든 치료에 저항했다."},{t:5,en:"Negotiators struggled with the intractable conflict.",kr:"협상가들은 해결하기 힘든 갈등에 애를 먹었다."}]},
  "intransigence": {img:"🚧", ex5:[{t:1,en:"The talks collapsed because of his intransigence.",kr:"협상은 그의 비타협적 태도 때문에 결렬되었다."},{t:2,en:"Her intransigence on the budget angered the board.",kr:"예산에 대한 그녀의 완강함은 이사회를 화나게 했다."},{t:3,en:"Years of intransigence hardened both sides.",kr:"수년간의 비타협이 양쪽을 더 완고하게 만들었다."},{t:4,en:"Mutual intransigence kept the two nations at odds.",kr:"상호 간의 비타협이 두 나라를 계속 대립하게 했다."},{t:5,en:"His sheer intransigence ruined any chance of compromise.",kr:"그의 순전한 완고함이 타협의 기회를 모두 망쳤다."}]},
  "intransigent": {img:"🚫", ex5:[{t:1,en:"He remained intransigent on the issue.",kr:"그는 그 문제에 대해 완강하게 버텼다."},{t:2,en:"Their intransigent stance blocked the deal.",kr:"그들의 비타협적 태도가 거래를 막았다."},{t:3,en:"She was intransigent about the rules.",kr:"그녀는 규칙에 대해 한 치도 물러서지 않았다."},{t:4,en:"An intransigent few halted progress.",kr:"완고한 소수가 진전을 멈춰 세웠다."},{t:5,en:"The talks failed over intransigent demands.",kr:"비타협적 요구로 협상이 결렬됐다."}]},
  "intrepid": {img:"🧗", ex5:[{t:1,en:"The intrepid explorer crossed the ice.",kr:"그 대담한 탐험가는 얼음을 건넜다."},{t:2,en:"She is an intrepid traveler.",kr:"그녀는 겁 없는 여행가다."},{t:3,en:"The intrepid team climbed the peak.",kr:"그 대담한 팀이 봉우리를 올랐다."},{t:4,en:"His intrepid spirit inspired others.",kr:"그의 대담한 정신이 다른 이들을 고무시켰다."},{t:5,en:"Intrepid sailors faced the rough sea.",kr:"대담한 선원들이 거친 바다에 맞섰다."}]},
  "intricacy": {img:"🧩", ex5:[{t:1,en:"The intricacy of the design amazed us.",kr:"그 디자인의 정교함이 우리를 놀라게 했다."},{t:2,en:"She admired the intricacy of the lace.",kr:"그녀는 그 레이스의 정교함에 감탄했다."},{t:3,en:"The plan had a surprising intricacy.",kr:"그 계획에는 놀라운 복잡함이 있었다."},{t:4,en:"He explained the intricacy step by step.",kr:"그는 그 복잡함을 단계별로 설명했다."},{t:5,en:"The clock's intricacy took years to build.",kr:"그 시계의 정교함은 만드는 데 여러 해가 걸렸다."}]},
