  "journalist": {img:"📰", ex5:[{t:1,en:"The journalist asked questions.",kr:"기자가 질문을 던졌다."},{t:2,en:"The journalist is bold.",kr:"그 기자는 대담하다."},{t:3,en:"We met a journalist.",kr:"우리는 기자를 만났다."},{t:4,en:"The journalist gave us a scoop.",kr:"그 기자는 우리에게 특종을 알려주었다."},{t:5,en:"We found the journalist sharp.",kr:"우리는 그 기자가 예리하다고 느꼈다."}]},
  "journey": {img:"🧳", ex5:[{t:1,en:"The journey is long.",kr:"그 여정은 길다."},{t:2,en:"The journey began.",kr:"그 여정이 시작됐다."},{t:3,en:"We took a journey.",kr:"우리는 여정에 올랐다."},{t:4,en:"The trip gave us a journey.",kr:"그 여행은 우리에게 여정을 안겼다."},{t:5,en:"We found the journey worth it.",kr:"우리는 그 여정이 보람 있다고 느꼈다."}]},
  "jovial": {img:"😄", ex5:[{t:1,en:"The jovial host welcomed everyone.",kr:"그 유쾌한 주인은 모두를 반겼다."},{t:2,en:"He was in a jovial mood.",kr:"그는 유쾌한 기분이었다."},{t:3,en:"Her jovial laugh filled the room.",kr:"그녀의 명랑한 웃음이 방을 채웠다."},{t:4,en:"The party had a jovial spirit.",kr:"그 파티는 유쾌한 분위기였다."},{t:5,en:"His jovial nature made him popular.",kr:"그의 쾌활한 성품이 그를 인기 있게 했다."}]},
  "joy": {img:"😄", ex5:[{t:1,en:"Joy filled the room.",kr:"기쁨이 방을 채웠다."},{t:2,en:"The joy is pure.",kr:"그 기쁨은 순수하다."},{t:3,en:"We felt joy.",kr:"우리는 기쁨을 느꼈다."},{t:4,en:"The win gave us joy.",kr:"그 승리는 우리에게 기쁨을 안겼다."},{t:5,en:"We found the joy contagious.",kr:"우리는 그 기쁨이 전염된다고 느꼈다."}]},
  "jubilant": {img:"🎉", ex5:[{t:1,en:"The fans were jubilant after the win.",kr:"팬들은 승리 후 환호했다."},{t:2,en:"She felt jubilant at the good news.",kr:"그녀는 그 좋은 소식에 크게 기뻐했다."},{t:3,en:"A jubilant crowd filled the square.",kr:"환희에 찬 군중이 광장을 채웠다."},{t:4,en:"They gave a jubilant cheer.",kr:"그들은 환호성을 질렀다."},{t:5,en:"The team was jubilant at the title.",kr:"그 팀은 우승에 크게 기뻐했다."}]},
  "jubilantly": {img:"🎉", ex5:[{t:1,en:"The fans cheered jubilantly at the win.",kr:"팬들은 승리에 환호성을 지르며 기뻐했다."},{t:2,en:"She jubilantly announced the good news.",kr:"그녀는 그 좋은 소식을 신이 나서 알렸다."},{t:3,en:"The crowd celebrated jubilantly.",kr:"군중은 환희에 차서 축하했다."},{t:4,en:"They danced jubilantly in the street.",kr:"그들은 거리에서 환희에 차서 춤췄다."},{t:5,en:"The team jubilantly lifted the trophy.",kr:"그 팀은 환희에 차서 트로피를 들어 올렸다."}]},
  "jubilee": {img:"🎉", ex5:[{t:1,en:"The town held a grand jubilee for its anniversary.",kr:"그 마을은 기념일을 맞아 성대한 축제를 열었다."},{t:2,en:"Crowds celebrated the queen's golden jubilee.",kr:"군중은 여왕의 즉위 50주년 기념제를 축하했다."},{t:3,en:"The jubilee marked fifty years of the school.",kr:"그 기념 행사는 학교 설립 50주년을 기렸다."},{t:4,en:"Music and dancing filled the joyful jubilee.",kr:"음악과 춤이 기쁨에 찬 축제를 가득 채웠다."},{t:5,en:"The whole city joined the silver jubilee parade.",kr:"도시 전체가 25주년 기념 행진에 함께했다."}]},
