  "judgment": {img:"⚖️", ex5:[{t:1,en:"The judgment is final.",kr:"그 판결은 최종적이다."},{t:2,en:"The judgment is fair.",kr:"그 판단은 공정하다."},{t:3,en:"We trust her judgment.",kr:"우리는 그녀의 판단을 믿는다."},{t:4,en:"The court gave us a judgment.",kr:"그 법원은 우리에게 판결을 내렸다."},{t:5,en:"We found the judgment sound.",kr:"우리는 그 판단이 타당하다고 느꼈다."}]},
  "jug": {img:"🍶", ex5:[{t:1,en:"She filled the jug with cold water.",kr:"그녀는 주전자에 찬물을 채웠다."},{t:2,en:"He poured milk from the jug.",kr:"그는 주전자에서 우유를 따랐다."},{t:3,en:"A clay jug stood on the shelf.",kr:"흙으로 만든 단지가 선반에 놓여 있었다."},{t:4,en:"The jug holds two liters of juice.",kr:"그 주전자는 주스 2리터를 담는다."},{t:5,en:"They carried water in a heavy jug.",kr:"그들은 무거운 물주전자에 물을 날랐다."}]},
  "juice": {img:"🧃", ex5:[{t:1,en:"The juice is fresh.",kr:"그 주스는 신선하다."},{t:2,en:"The juice is sweet.",kr:"그 주스는 달다."},{t:3,en:"We poured juice.",kr:"우리는 주스를 따랐다."},{t:4,en:"The bar gave us juice.",kr:"그 바는 우리에게 주스를 주었다."},{t:5,en:"We found the juice sour.",kr:"우리는 그 주스가 시다고 느꼈다."}]},
  "juicy": {img:"🍑", ex5:[{t:1,en:"The peach was sweet and juicy.",kr:"그 복숭아는 달고 즙이 많았다."},{t:2,en:"She bit into a juicy orange.",kr:"그녀는 즙이 많은 오렌지를 한 입 베어 물었다."},{t:3,en:"The steak was tender and juicy.",kr:"그 스테이크는 부드럽고 육즙이 풍부했다."},{t:4,en:"Ripe tomatoes are red and juicy.",kr:"잘 익은 토마토는 빨갛고 즙이 많다."},{t:5,en:"He enjoyed a juicy slice of melon.",kr:"그는 즙이 많은 멜론 한 조각을 즐겼다."}]},
