  "mercantile": {img:"⚓", ex5:[{t:1,en:"The port thrived on mercantile trade.",kr:"그 항구는 상업 무역으로 번영했다."},{t:2,en:"He came from a wealthy mercantile family.",kr:"그는 부유한 상인 가문 출신이었다."},{t:3,en:"The city had a strong mercantile tradition.",kr:"그 도시는 강한 상업 전통을 지녔다."},{t:4,en:"Mercantile law governs commercial dealings.",kr:"상법은 상거래를 규율한다."},{t:5,en:"Their mercantile interests spanned the globe.",kr:"그들의 상업적 이해관계는 전 세계에 걸쳐 있었다."}]},
  "mercantilism": {img:"⚓", ex5:[{t:1,en:"Mercantilism favored exports over imports.",kr:"중상주의는 수입보다 수출을 선호했다."},{t:2,en:"Mercantilism shaped early colonial policy.",kr:"중상주의는 초기 식민 정책을 형성했다."},{t:3,en:"Under mercantilism, gold meant power.",kr:"중상주의 아래에서 금은 곧 힘을 의미했다."},{t:4,en:"Critics argued against mercantilism.",kr:"비판자들은 중상주의에 반대했다."},{t:5,en:"Mercantilism dominated European trade for centuries.",kr:"중상주의는 수 세기 동안 유럽 무역을 지배했다."}]},
  "mercenary": {img:"💰", ex5:[{t:1,en:"His motives were purely mercenary.",kr:"그의 동기는 순전히 돈벌이였다."},{t:2,en:"They hired a mercenary to fight.",kr:"그들은 싸우려고 용병을 고용했다."},{t:3,en:"She was too mercenary to care.",kr:"그녀는 너무 돈만 밝혀 신경 쓰지 않았다."},{t:4,en:"A mercenary deal left no goodwill.",kr:"돈에 좌우된 거래는 호의를 남기지 않았다."},{t:5,en:"He took a mercenary view of art.",kr:"그는 예술을 돈벌이 관점에서 봤다."}]},
  "merchant": {img:"🧑‍💼", ex5:[{t:1,en:"The merchant sold goods.",kr:"그 상인은 물건을 팔았다."},{t:2,en:"The merchant is shrewd.",kr:"그 상인은 영리하다."},{t:3,en:"We met a merchant.",kr:"우리는 상인을 만났다."},{t:4,en:"The merchant gave us a deal.",kr:"그 상인은 우리에게 흥정을 제안했다."},{t:5,en:"We found the merchant fair.",kr:"우리는 그 상인이 공정하다고 느꼈다."}]},
  "mercurial": {img:"🌡️", ex5:[{t:1,en:"He has a mercurial temper.",kr:"그는 변덕스러운 성미를 지녔다."},{t:2,en:"Her mercurial moods were hard to predict.",kr:"그녀의 변덕스러운 기분은 예측하기 어려웠다."},{t:3,en:"The mercurial weather changed all day.",kr:"변덕스러운 날씨가 하루 종일 바뀌었다."},{t:4,en:"His mercurial nature kept us guessing.",kr:"그의 변덕스러운 성격이 우리를 헷갈리게 했다."},{t:5,en:"The market was mercurial that week.",kr:"그 주의 시장은 변덕스러웠다."}]},
  "mercury": {img:"🌡️", ex5:[{t:1,en:"The thermometer used mercury.",kr:"그 온도계는 수은을 사용했다."},{t:2,en:"Mercury is a liquid metal.",kr:"수은은 액체 상태의 금속이다."},{t:3,en:"The mercury rose as the day grew hot.",kr:"날이 더워지자 수은주가 올라갔다."},{t:4,en:"Mercury can be harmful if swallowed.",kr:"수은은 삼키면 해로울 수 있다."},{t:5,en:"Old switches sometimes held mercury.",kr:"옛 스위치에는 때때로 수은이 들어 있었다."}]},
  "mercy": {img:"🙏", ex5:[{t:1,en:"Mercy softened them.",kr:"자비가 그들을 누그러뜨렸다."},{t:2,en:"The mercy is rare.",kr:"그 자비는 드물다."},{t:3,en:"We showed mercy.",kr:"우리는 자비를 베풀었다."},{t:4,en:"The judge gave us mercy.",kr:"그 판사는 우리에게 관용을 베풀었다."},{t:5,en:"We found the mercy genuine.",kr:"우리는 그 자비가 진심이라고 느꼈다."}]},
  "mere": {img:"🤏", ex5:[{t:1,en:"It was a mere guess.",kr:"그것은 단순한 추측이었다."},{t:2,en:"The mere thought scares us.",kr:"그 생각만으로도 우리는 무섭다."},{t:3,en:"We paid a mere coin.",kr:"우리는 동전 한 닢만 냈다."},{t:4,en:"It gave us a mere hint.",kr:"그것은 우리에게 그저 힌트만 주었다."},{t:5,en:"We found a mere trace.",kr:"우리는 흔적만 겨우 찾았다."}]},
  "merely": {img:"🔹", ex5:[{t:1,en:"It is merely a draft.",kr:"그것은 그저 초안일 뿐이다."},{t:2,en:"She merely smiled.",kr:"그녀는 그저 미소만 지었다."},{t:3,en:"We merely asked.",kr:"우리는 그저 물었을 뿐이다."},{t:4,en:"It merely gave us a clue.",kr:"그것은 우리에게 단지 단서만 주었다."},{t:5,en:"We found it merely a start.",kr:"우리는 그것이 그저 시작일 뿐임을 알았다."}]},
  "meretricious": {img:"💄", ex5:[{t:1,en:"The decor was gaudy and meretricious.",kr:"그 장식은 야하고 겉만 번지르르했다."},{t:2,en:"Critics called the work meretricious.",kr:"비평가들은 그 작품을 겉만 화려하다고 평했다."},{t:3,en:"His meretricious charm fooled few.",kr:"그의 가식적인 매력은 거의 통하지 않았다."},{t:4,en:"The ad made meretricious claims.",kr:"그 광고는 그럴싸한 거짓 주장을 했다."},{t:5,en:"A meretricious shine hid poor quality.",kr:"번지르르한 광택이 낮은 품질을 가렸다."}]},
