  "portray": {img:"🖼️", ex5:[{t:1,en:"The film portrays life in the past.",kr:"그 영화는 과거의 삶을 그린다."},{t:2,en:"She portrayed the queen in the play.",kr:"그녀는 그 연극에서 여왕을 연기했다."},{t:3,en:"The book portrays a small village.",kr:"그 책은 작은 마을을 묘사한다."},{t:4,en:"The artist portrayed her with great care.",kr:"그 화가는 그녀를 정성스럽게 그렸다."},{t:5,en:"The story portrays hope and courage.",kr:"그 이야기는 희망과 용기를 그린다."}]},
  "pose": {img:"🤳", ex5:[{t:1,en:"We pose for a photo.",kr:"우리는 사진을 위해 자세를 잡는다."},{t:2,en:"The risk poses a threat.",kr:"그 위험이 위협이 된다."},{t:3,en:"We pose a question.",kr:"우리는 질문을 제기한다."},{t:4,en:"The shot gave us a pose.",kr:"그 촬영은 우리에게 포즈를 잡게 했다."},{t:5,en:"We hold the pose still.",kr:"우리는 그 자세를 가만히 유지한다."}]},
  "posit": {img:"💭", ex5:[{t:1,en:"The scientist posited a new theory of light.",kr:"그 과학자는 빛에 관한 새로운 이론을 가정했다."},{t:2,en:"Let us posit that the witness was telling the truth.",kr:"증인이 진실을 말하고 있었다고 가정해 보자."},{t:3,en:"Philosophers posit the existence of an objective reality.",kr:"철학자들은 객관적 실재의 존재를 상정한다."},{t:4,en:"The paper posits a link between diet and longevity.",kr:"그 논문은 식단과 장수 사이의 연관성을 상정한다."},{t:5,en:"She posited several reasons for the unexpected result.",kr:"그녀는 예상치 못한 결과에 대해 여러 이유를 가정했다."}]},
  "position": {img:"📍", ex5:[{t:1,en:"The position is open.",kr:"그 자리는 비어 있다."},{t:2,en:"The position shifted.",kr:"그 위치가 바뀌었다."},{t:3,en:"We took a position.",kr:"우리는 입장을 정했다."},{t:4,en:"The firm gave us a position.",kr:"그 회사는 우리에게 직책을 주었다."},{t:5,en:"We found the position strong.",kr:"우리는 그 위치가 유리하다고 느꼈다."}]},
  "positive": {img:"➕", ex5:[{t:1,en:"The result is positive.",kr:"그 결과는 긍정적이다."},{t:2,en:"The mood is positive.",kr:"그 분위기는 긍정적이다."},{t:3,en:"We stayed positive.",kr:"우리는 긍정을 유지했다."},{t:4,en:"The test gave us a positive sign.",kr:"그 검사는 우리에게 긍정적 신호를 주었다."},{t:5,en:"We found the review positive.",kr:"우리는 그 평이 긍정적이라고 느꼈다."}]},
