  "relegation": {img:"⬇️", ex5:[{t:1,en:"The team faced relegation to a lower division.",kr:"그 팀은 하위 디비전으로의 강등에 직면했다."},{t:2,en:"Defeat meant relegation at the end of the season.",kr:"패배는 시즌 말 강등을 의미했다."},{t:3,en:"His relegation to a minor role disappointed him.",kr:"하찮은 역할로의 좌천은 그를 실망시켰다."},{t:4,en:"The club narrowly avoided relegation this year.",kr:"그 클럽은 올해 가까스로 강등을 면했다."},{t:5,en:"Relegation to the back office felt like a demotion.",kr:"뒤편 사무실로의 좌천은 강등처럼 느껴졌다."}]},
  "relentless": {img:"🌊", ex5:[{t:1,en:"The rain was relentless all night.",kr:"비가 밤새 끊임없이 내렸다."},{t:2,en:"She made a relentless effort.",kr:"그녀는 끈질긴 노력을 기울였다."},{t:3,en:"The team's pursuit was relentless.",kr:"그 팀의 추격은 집요했다."},{t:4,en:"His relentless drive led to success.",kr:"그의 끈질긴 추진력이 성공으로 이어졌다."},{t:5,en:"The relentless heat tired everyone.",kr:"끊임없는 더위가 모두를 지치게 했다."}]},
  "relentlessly": {img:"🔁", ex5:[{t:1,en:"The rain fell relentlessly for days.",kr:"비가 며칠 동안 끊임없이 내렸다."},{t:2,en:"She pursued her goal relentlessly.",kr:"그녀는 자신의 목표를 끈질기게 추구했다."},{t:3,en:"The critics attacked the film relentlessly.",kr:"비평가들은 그 영화를 가차 없이 공격했다."},{t:4,en:"He worked relentlessly to finish on time.",kr:"그는 제때 끝내려고 쉼 없이 일했다."},{t:5,en:"The team pressed forward relentlessly.",kr:"그 팀은 가차 없이 밀고 나아갔다."}]},
  "relevant": {img:"🔗", ex5:[{t:1,en:"The point is relevant.",kr:"그 요점은 관련이 있다."},{t:2,en:"The data is relevant.",kr:"그 데이터는 적절하다."},{t:3,en:"We kept it relevant.",kr:"우리는 그것을 관련되게 유지했다."},{t:4,en:"The search gave us a relevant hit.",kr:"그 검색은 우리에게 적절한 결과를 주었다."},{t:5,en:"We found the fact relevant.",kr:"우리는 그 사실이 관련 있다고 느꼈다."}]},
  "reliable": {img:"🤝", ex5:[{t:1,en:"The car is reliable.",kr:"그 차는 믿을 만하다."},{t:2,en:"The source is reliable.",kr:"그 출처는 신뢰할 만하다."},{t:3,en:"We hired a reliable hand.",kr:"우리는 믿음직한 일꾼을 고용했다."},{t:4,en:"The tool gave us reliable data.",kr:"그 도구는 우리에게 신뢰할 데이터를 주었다."},{t:5,en:"We found the partner reliable.",kr:"우리는 그 파트너가 믿음직하다고 느꼈다."}]},
  "relic": {img:"🏺", ex5:[{t:1,en:"The museum displayed a sacred relic.",kr:"박물관은 신성한 유물을 전시했다."},{t:2,en:"That old phone is a relic of the past.",kr:"그 낡은 전화기는 과거의 유물이다."},{t:3,en:"Pilgrims came to see the holy relic.",kr:"순례자들은 그 성스러운 유물을 보러 왔다."},{t:4,en:"The ruined wall is a relic of the war.",kr:"무너진 그 벽은 전쟁의 잔재이다."},{t:5,en:"Archaeologists dug up an ancient relic.",kr:"고고학자들이 고대 유물을 발굴했다."}]},
  "relief": {img:"😌", ex5:[{t:1,en:"The relief is great.",kr:"그 안도감은 크다."},{t:2,en:"The relief came fast.",kr:"그 구호가 빠르게 왔다."},{t:3,en:"We felt relief.",kr:"우리는 안도를 느꼈다."},{t:4,en:"The news gave us relief.",kr:"그 소식은 우리에게 안도를 안겼다."},{t:5,en:"We found the relief welcome.",kr:"우리는 그 안도가 반갑다고 느꼈다."}]},
