  "silent": {img:"🔇", ex5:[{t:1,en:"The room is silent.",kr:"그 방은 고요하다."},{t:2,en:"The film is silent.",kr:"그 영화는 무성 영화다."},{t:3,en:"We stayed silent.",kr:"우리는 잠자코 있었다."},{t:4,en:"The night gave us a silent hour.",kr:"그 밤은 우리에게 고요한 시간을 안겼다."},{t:5,en:"We found the hall silent.",kr:"우리는 그 홀이 고요하다고 느꼈다."}]},
  "silhouette": {img:"👤", ex5:[{t:1,en:"His silhouette appeared in the doorway.",kr:"그의 실루엣이 문간에 나타났다."},{t:2,en:"The hills made a dark silhouette at dusk.",kr:"언덕들은 황혼 녘에 어두운 윤곽을 이루었다."},{t:3,en:"The dress had a slim, elegant silhouette.",kr:"그 드레스는 날씬하고 우아한 윤곽을 지녔다."},{t:4,en:"She drew his silhouette in black ink.",kr:"그녀는 검은 잉크로 그의 실루엣을 그렸다."},{t:5,en:"A bird's silhouette crossed the moon.",kr:"새 한 마리의 실루엣이 달을 가로질렀다."}]},
  "silicon": {img:"💻", ex5:[{t:1,en:"Computer chips are made of silicon.",kr:"컴퓨터 칩은 실리콘으로 만들어진다."},{t:2,en:"Silicon is the second most common element in the crust.",kr:"실리콘은 지각에서 두 번째로 흔한 원소다."},{t:3,en:"The factory produced silicon wafers.",kr:"그 공장은 실리콘 웨이퍼를 생산했다."},{t:4,en:"Silicon is a key material in electronics.",kr:"실리콘은 전자공학의 핵심 재료다."},{t:5,en:"Pure silicon has a shiny, gray surface.",kr:"순수한 실리콘은 반짝이는 회색 표면을 지닌다."}]},
  "silk": {img:"🧣", ex5:[{t:1,en:"The silk is soft.",kr:"그 비단은 부드럽다."},{t:2,en:"The silk is fine.",kr:"그 비단은 고급이다."},{t:3,en:"We wore silk.",kr:"우리는 비단옷을 입었다."},{t:4,en:"The shop gave us silk cloth.",kr:"그 가게는 우리에게 비단 천을 주었다."},{t:5,en:"We found the silk smooth.",kr:"우리는 그 비단이 매끄럽다고 느꼈다."}]},
  "silkworm": {img:"🐛", ex5:[{t:1,en:"The silkworm spins a fine silk cocoon.",kr:"누에는 고운 비단 고치를 짓는다."},{t:2,en:"A silkworm feeds only on mulberry leaves.",kr:"누에는 오직 뽕잎만 먹는다."},{t:3,en:"They raised silkworms for the silk industry.",kr:"그들은 비단 산업을 위해 누에를 길렀다."},{t:4,en:"The silkworm grows quickly before spinning.",kr:"누에는 고치를 짓기 전에 빠르게 자란다."},{t:5,en:"Each silkworm produces a long silk thread.",kr:"누에 한 마리는 긴 비단실을 만들어 낸다."}]},
  "silky": {img:"🧣", ex5:[{t:1,en:"The scarf felt soft and silky.",kr:"그 스카프는 부드럽고 매끄러웠다."},{t:2,en:"She has long silky hair.",kr:"그녀는 길고 매끄러운 머리카락을 가졌다."},{t:3,en:"The cream had a silky texture.",kr:"그 크림은 매끄러운 질감이었다."},{t:4,en:"His silky voice calmed the crowd.",kr:"그의 부드러운 목소리가 군중을 진정시켰다."},{t:5,en:"The petals were smooth and silky.",kr:"꽃잎은 매끄럽고 부드러웠다."}]},
